// Dati ANNO GIUSTO (IT + EN/ES allineati per indice)
var ANNO_GIUSTO_DATA=[{"q":"La caduta del Muro di Berlino","risposta":1989,"curiosita":"Il 9 novembre 1989 migliaia di berlinesi abbatterono il muro che divideva la città dal 1961. Fu la fine simbolica della Guerra Fredda."},
{"q":"Il primo sbarco dell'uomo sulla Luna","risposta":1969,"curiosita":"Il 20 luglio 1969 Neil Armstrong e Buzz Aldrin atterrarono con l'Apollo 11. Armstrong disse: 'Un piccolo passo per un uomo, un balzo gigante per l'umanità'."},
{"q":"La nascita di Internet (ARPANET)","risposta":1969,"curiosita":"Il 29 ottobre 1969 fu inviato il primo messaggio su ARPANET: 'lo'. Il sistema crashò dopo due lettere, ma la rete era nata."},
{"q":"L'invenzione della stampa a caratteri mobili di Gutenberg","risposta":1450,"curiosita":"Intorno al 1450 Gutenberg inventò la stampa a caratteri mobili. La Bibbia di Gutenberg fu il primo libro stampato in Europa — circa 180 copie."},
{"q":"La scoperta dell'America da parte di Colombo","risposta":1492,"curiosita":"Il 12 ottobre 1492 Colombo avvistò terra nei Caraibi. Credeva di essere arrivato in Asia — morì senza sapere di aver trovato un nuovo continente."},
{"q":"La prima Rivoluzione Industriale (inizio)","risposta":1760,"curiosita":"La Rivoluzione Industriale iniziò in Inghilterra attorno al 1760, con innovazioni come la macchina a vapore perfezionata da James Watt. Cambiò per sempre il lavoro umano."},
{"q":"La Rivoluzione Francese (inizio)","risposta":1789,"curiosita":"Il 14 luglio 1789 cadde la Bastiglia. La Rivoluzione Francese diede al mondo i concetti di libertà, uguaglianza e fraternità."},
{"q":"La nascita di Leonardo da Vinci","risposta":1452,"curiosita":"Leonardo nacque il 15 aprile 1452 ad Anchiano, vicino Vinci. Pittore, scienziato, ingegnere: il più completo genio del Rinascimento."},
{"q":"La morte di Napoleone Bonaparte","risposta":1821,"curiosita":"Napoleone morì il 5 maggio 1821 sull'isola di Sant'Elena, in esilio. Aveva 51 anni. Ancora oggi si discute se fu avvelenato con l'arsenico."},
{"q":"La fondazione di Roma (secondo la tradizione)","risposta":-753,"curiosita":"Secondo la tradizione Romolo fondò Roma nel 753 a.C. In realtà i primi insediamenti nella zona risalgono al 1000 a.C. circa."},
{"q":"La Prima Guerra Mondiale (inizio)","risposta":1914,"curiosita":"Il 28 giugno 1914 fu assassinato l'arciduca Francesco Ferdinando a Sarajevo. Quattro anni dopo, la guerra aveva causato oltre 20 milioni di morti."},
{"q":"La Seconda Guerra Mondiale (fine)","risposta":1945,"curiosita":"Il 2 settembre 1945 il Giappone firmò la resa dopo le bombe atomiche su Hiroshima e Nagasaki. 70-85 milioni di persone morirono nel conflitto."},
{"q":"Il lancio del primo iPhone","risposta":2007,"curiosita":"Steve Jobs presentò il primo iPhone il 9 gennaio 2007. Lo descrisse come 'un iPod, un telefono e un comunicatore Internet'. Nessuno capì subito quanto avrebbe cambiato tutto."},
{"q":"La nascita di Facebook","risposta":2004,"curiosita":"Mark Zuckerberg lanciò Facebook il 4 febbraio 2004 da Harvard. Inizialmente si chiamava 'TheFacebook' ed era solo per studenti universitari."},
{"q":"La nascita di YouTube","risposta":2005,"curiosita":"YouTube fu fondato il 14 febbraio 2005 da tre ex dipendenti di PayPal. Il primo video si chiamava 'Me at the zoo' ed è ancora online."},
{"q":"La nascita di Google","risposta":1998,"curiosita":"Larry Page e Sergey Brin fondarono Google il 4 settembre 1998 in un garage a Menlo Park. Il nome deriva da 'googol', il numero 10 elevato alla centesima."},
{"q":"La pubblicazione del primo tweet su Twitter","risposta":2006,"curiosita":"Jack Dorsey pubblicò il primo tweet il 21 marzo 2006: 'just setting up my twttr'. La piattaforma fu lanciata al pubblico nel luglio dello stesso anno."},
{"q":"La caduta dell'Impero Romano d'Occidente","risposta":476,"curiosita":"Nel 476 d.C. Odoacre depose l'ultimo imperatore romano Romolo Augustolo. Convenzionalmente segna la fine dell'antichità e l'inizio del Medioevo."},
{"q":"La nascita di William Shakespeare","risposta":1564,"curiosita":"Shakespeare nacque il 23 aprile 1564 a Stratford-upon-Avon. Scrisse 37 opere teatrali e 154 sonetti. Ancora oggi è il drammaturgo più rappresentato al mondo."},
{"q":"La pubblicazione della teoria della relatività di Einstein","risposta":1905,"curiosita":"Nel 1905 Einstein pubblicò quattro articoli rivoluzionari, tra cui la relatività ristretta e E=mc². Fu chiamato il suo 'anno dei miracoli'."},
{"q":"La costruzione della Grande Muraglia Cinese (inizio)","risposta":-221,"curiosita":"La Grande Muraglia iniziò ad essere costruita nel 221 a.C. sotto l'imperatore Qin Shi Huang. Non è visibile ad occhio nudo dallo spazio, contrariamente alla leggenda."},
{"q":"La nascita di Isaac Newton","risposta":1643,"curiosita":"Newton nacque il 4 gennaio 1643 in Inghilterra. La leggenda della mela caduta lo avrebbe portato alla teoria della gravitazione universale."},
{"q":"La morte di Giulio Cesare","risposta":-44,"curiosita":"Giulio Cesare fu assassinato il 15 marzo del 44 a.C. alle Idi di Marzo. Ricevette 23 pugnalate dai senatori, guidati da Bruto e Cassio."},
{"q":"La costruzione del Colosseo (inaugurazione)","risposta":80,"curiosita":"Il Colosseo fu inaugurato nell'80 d.C. dall'imperatore Tito con 100 giorni di giochi. Poteva ospitare fino a 80.000 spettatori."},
{"q":"La Rivoluzione Russa (ottobre)","risposta":1917,"curiosita":"La Rivoluzione d'Ottobre 1917 portò al potere i bolscevichi di Lenin. Nacque il primo stato comunista della storia, che durò fino al 1991."},
{"q":"L'invenzione del telefono da parte di Bell","risposta":1876,"curiosita":"Alexander Graham Bell brevettò il telefono il 7 marzo 1876. La prima frase trasmessa fu: 'Watson, vieni qui, ho bisogno di te'."},
{"q":"La nascita di Mozart","risposta":1756,"curiosita":"Wolfgang Amadeus Mozart nacque il 27 gennaio 1756 a Salisburgo. Compose la sua prima sinfonia a 8 anni. Morì a 35 anni lasciando oltre 600 composizioni."},
{"q":"La nascita di Michelangelo","risposta":1475,"curiosita":"Michelangelo nacque il 6 marzo 1475. Dipinse la Cappella Sistina tra il 1508 e il 1512, lavorando per quattro anni quasi sempre sdraiato su un'impalcatura."},
{"q":"La pubblicazione della Divina Commedia di Dante","risposta":1321,"curiosita":"Dante completò la Divina Commedia poco prima di morire nel 1321. È considerata la più grande opera della letteratura italiana e una delle più importanti al mondo."},
{"q":"La fine dell'apartheid in Sudafrica","risposta":1994,"curiosita":"Nel 1994 si tennero le prime elezioni democratiche in Sudafrica. Nelson Mandela, dopo 27 anni di carcere, diventò il primo presidente nero del paese."},
{"q":"Il lancio dello Sputnik (primo satellite artificiale)","risposta":1957,"curiosita":"Il 4 ottobre 1957 l'URSS lanciò lo Sputnik, il primo satellite artificiale della storia. Era grande come una palla da basket e trasmetteva solo un segnale radio."},
{"q":"La fondazione delle Nazioni Unite","risposta":1945,"curiosita":"Le Nazioni Unite furono fondate il 24 ottobre 1945 da 51 paesi dopo la Seconda Guerra Mondiale. Oggi ne fanno parte 193 stati."},
{"q":"La firma della Magna Carta","risposta":1215,"curiosita":"La Magna Carta fu firmata il 15 giugno 1215 dal re Giovanni d'Inghilterra. È considerata la base del diritto costituzionale moderno."},
{"q":"La nascita di Albert Einstein","risposta":1879,"curiosita":"Einstein nacque il 14 marzo 1879 a Ulm, in Germania. A scuola non era particolarmente brillante — il mito che fosse bocciato è però falso."},
{"q":"La nascita di Galileo Galilei","risposta":1564,"curiosita":"Galileo nacque il 15 febbraio 1564 a Pisa. Perfezionò il telescopio e lo puntò verso il cielo, sostenendo che la Terra gira attorno al Sole — per questo fu processato dall'Inquisizione."},
{"q":"La fondazione dell'Unione Europea (Trattato di Maastricht)","risposta":1993,"curiosita":"Il Trattato di Maastricht entrò in vigore il 1° novembre 1993, creando formalmente l'Unione Europea. Aprì la strada all'euro e alla libera circolazione."},
{"q":"Il lancio di Amazon","risposta":1994,"curiosita":"Jeff Bezos fondò Amazon il 5 luglio 1994 in un garage di Seattle. Inizialmente vendeva solo libri. Oggi è uno dei marketplace più grandi del mondo."},
{"q":"La nascita di Cleopatra","risposta":-69,"curiosita":"Cleopatra nacque nel 69 a.C. Era di origini greche macedoni, non egizia. Fu l'ultima regina dei Tolomei e parlava 9 lingue."},
{"q":"La costruzione delle piramidi di Giza (inizio)","risposta":-2560,"curiosita":"La Grande Piramide di Giza fu costruita intorno al 2560 a.C. per il faraone Cheope. Per oltre 3.800 anni fu la struttura più alta del mondo."},
{"q":"La nascita di Gesù Cristo (stima storica)","risposta":-4,"curiosita":"Ironicamente, Gesù nacque probabilmente tra il 6 e il 4 a.C. L'errore nel calendario fu fatto dal monaco Dionigi il Piccolo nel VI secolo."},
{"q":"La fondazione di Venezia","risposta":421,"curiosita":"Venezia fu fondata tradizionalmente il 25 marzo 421 d.C. Fu costruita su 118 isole collegate da 400 ponti. Per secoli fu la potenza commerciale del Mediterraneo."},
{"q":"La nascita di Napoleone Bonaparte","risposta":1769,"curiosita":"Napoleone nacque il 15 agosto 1769 ad Ajaccio, in Corsica. Era corso, non francese. E non era basso: misurava circa 1,69 m — nella media per l'epoca."},
{"q":"La pubblicazione dell'Origine delle Specie di Darwin","risposta":1859,"curiosita":"Darwin pubblicò 'L'origine delle specie' il 24 novembre 1859. Le 1.250 copie della prima edizione andarono esaurite in un giorno."},
{"q":"La nascita di Karl Marx","risposta":1818,"curiosita":"Karl Marx nacque il 5 maggio 1818 a Treviri. Il Manifesto del Partito Comunista, scritto con Engels, fu pubblicato nel 1848."},
{"q":"La Peste Nera in Europa (picco)","risposta":1347,"curiosita":"La Peste Nera arrivò in Europa nel 1347 e in cinque anni uccise tra il 30 e il 60% della popolazione europea — circa 25 milioni di persone."},
{"q":"La nascita di Maometto","risposta":570,"curiosita":"Maometto nacque intorno al 570 d.C. alla Mecca. Ricevette le prime rivelazioni nel 610. L'Islam è oggi la religione con il più alto tasso di crescita al mondo."},
{"q":"L'invenzione della penicillina","risposta":1928,"curiosita":"Alexander Fleming scoprì la penicillina il 3 settembre 1928 per caso, notando che una muffa aveva ucciso i batteri in una capsula di Petri. Salvò milioni di vite."},
{"q":"La fine della Seconda Guerra Mondiale in Europa (V-E Day)","risposta":1945,"curiosita":"L'8 maggio 1945 la Germania firmò la resa incondizionata. Nelle strade di tutta Europa esplosero festeggiamenti spontanei. La guerra in Pacifico sarebbe finita ad agosto."},
{"q":"La nascita di Steve Jobs","risposta":1955,"curiosita":"Steve Jobs nacque il 24 febbraio 1955. Fu adottato alla nascita. Fondò Apple nel 1976 con Steve Wozniak in un garage. Rivoluzionò computer, musica, telefonia e animazione."},
{"q":"L'assassinio di John F. Kennedy","risposta":1963,"curiosita":"JFK fu assassinato il 22 novembre 1963 a Dallas durante un corteo presidenziale. Lee Harvey Oswald fu arrestato ma ucciso due giorni dopo da Jack Ruby."},
{"q":"La Prima Crociata (inizio)","risposta":1096,"curiosita":"La Prima Crociata fu indetta da papa Urbano II nel 1095. I crociati partirono nel 1096 e conquistarono Gerusalemme nel 1099 dopo un sanguinoso assedio."},
{"q":"La nascita di Charles Darwin","risposta":1809,"curiosita":"Darwin nacque il 12 febbraio 1809 — lo stesso giorno di Abraham Lincoln. Iniziò come studente di medicina, poi teologia, prima di diventare il più rivoluzionario naturalista della storia."},
{"q":"Il naufragio del Titanic","risposta":1912,"curiosita":"Il Titanic affondò il 15 aprile 1912 nel suo viaggio inaugurale. Morirono 1.517 persone. Fu scoperto sul fondo dell'Atlantico solo nel 1985."},
{"q":"La nascita di Adolf Hitler","risposta":1889,"curiosita":"Hitler nacque il 20 aprile 1889 in Austria. Fu due volte bocciato all'Accademia di Belle Arti di Vienna. Questa umiliazione influenzò profondamente la sua visione del mondo."},
{"q":"La fine dell'Unione Sovietica","risposta":1991,"curiosita":"Il 25 dicembre 1991 Gorbaciov si dimise e l'URSS cessò ufficialmente di esistere. Si divise in 15 stati indipendenti. La Guerra Fredda era finita."},
{"q":"La conquista dell'Everest (prima volta)","risposta":1953,"curiosita":"Il 29 maggio 1953 Edmund Hillary e Tenzing Norgay raggiunsero per primi la cima dell'Everest (8.849 m). La notizia arrivò a Londra il giorno dell'incoronazione della regina Elisabetta II."},
{"q":"L'invenzione della lampadina da parte di Edison","risposta":1879,"curiosita":"Edison brevettò la lampadina il 4 novembre 1879. In realtà molti ci avevano lavorato prima. Il suo merito fu renderla pratica e redditizia."},
{"q":"La fondazione di Apple","risposta":1976,"curiosita":"Apple fu fondata il 1° aprile 1976 da Steve Jobs, Steve Wozniak e Ronald Wayne. Wayne vendette la sua quota per 800 dollari — oggi varrebbe miliardi."},
{"q":"La nascita di Winston Churchill","risposta":1874,"curiosita":"Churchill nacque il 30 novembre 1874. Vinse il Nobel per la Letteratura nel 1953 — non per la Pace. Era un pittore appassionato e scrisse oltre 40 libri."},
{"q":"L'invenzione del cinema (fratelli Lumière)","risposta":1895,"curiosita":"Il 28 dicembre 1895 i fratelli Lumière proiettarono il primo film pubblico a Parigi. Secondo la leggenda, vedendo un treno arrivare sullo schermo, alcuni spettatori fuggirono spaventati."},
{"q":"La nascita di Frida Kahlo","risposta":1907,"curiosita":"Frida Kahlo nacque il 6 luglio 1907 a Coyoacán, Messico. Dopo un grave incidente a 18 anni iniziò a dipingere. La sua vita fu un intreccio indissolubile tra arte e dolore."},
{"q":"La prima trasmissione televisiva pubblica (BBC)","risposta":1936,"curiosita":"La BBC avviò il primo servizio televisivo pubblico regolare il 2 novembre 1936. Trasmetteva 2 ore al giorno. La TV fu sospesa durante la Seconda Guerra Mondiale."},
{"q":"La firma della Costituzione Italiana","risposta":1947,"curiosita":"La Costituzione Italiana fu approvata il 22 dicembre 1947 ed entrò in vigore il 1° gennaio 1948. Fu scritta dall'Assemblea Costituente dopo la fine del fascismo."},
{"q":"La nascita di Sigmund Freud","risposta":1856,"curiosita":"Freud nacque il 6 maggio 1856 a Freiberg. Fondò la psicoanalisi. Fumava 20 sigari al giorno e continuò anche dopo 33 operazioni alla mascella per un tumore."},
{"q":"L'invenzione del telefono cellulare (primo prototipo)","risposta":1973,"curiosita":"Il primo prototipo di cellulare fu usato da Martin Cooper di Motorola il 3 aprile 1973. Il telefono pesava circa 1 kg e offriva 30 minuti di conversazione."},
{"q":"La nascita di Nikola Tesla","risposta":1856,"curiosita":"Tesla nacque il 10 luglio 1856 nell'attuale Croazia, da famiglia serba. Sviluppò il sistema a corrente alternata. Morì povero e solo in una camera d'albergo nel 1943 — molti suoi brevetti erano finiti alla Westinghouse."},
{"q":"La nascita di Marie Curie","risposta":1867,"curiosita":"Marie Curie nacque il 7 novembre 1867 a Varsavia. Fu la prima donna a vincere il Nobel e l'unica a vincerlo in due discipline diverse (Fisica 1903, Chimica 1911)."},
{"q":"La caduta di Costantinopoli","risposta":1453,"curiosita":"Il 29 maggio 1453 i turchi ottomani di Maometto II conquistarono Costantinopoli, ponendo fine all'Impero Bizantino. Segnò convenzionalmente la fine del Medioevo."},
{"q":"Il Concilio di Trento (inizio)","risposta":1545,"curiosita":"Il Concilio di Trento iniziò nel 1545 e durò quasi 20 anni. Fu la risposta della Chiesa cattolica alla Riforma protestante di Lutero."},
{"q":"La nascita di Martin Luther King Jr.","risposta":1929,"curiosita":"MLK nacque il 15 gennaio 1929 ad Atlanta. Il suo discorso 'I Have a Dream' fu tenuto il 28 agosto 1963 davanti a 250.000 persone a Washington."},
{"q":"La prima bomba atomica sganciata su Hiroshima","risposta":1945,"curiosita":"Il 6 agosto 1945 la bomba atomica 'Little Boy' fu sganciata su Hiroshima. In pochi secondi morirono 80.000 persone. Entro fine anno le vittime salirono a 140.000."},
{"q":"La fondazione di Microsoft","risposta":1975,"curiosita":"Bill Gates e Paul Allen fondarono Microsoft il 4 aprile 1975 ad Albuquerque, New Mexico. Il nome unisce 'microcomputer' e 'software'."},
{"q":"La nascita di Walt Disney","risposta":1901,"curiosita":"Walt Disney nacque il 5 dicembre 1901 a Chicago. Creò Topolino nel 1928. Biancaneve (1937) fu il primo lungometraggio animato della Disney e un successo mondiale."},
{"q":"Il volo dei fratelli Wright (primo aereo a motore)","risposta":1903,"curiosita":"Il 17 dicembre 1903 Orville Wright volò per 12 secondi a Kitty Hawk. Pochi giornali diedero la notizia: per molti era troppo incredibile da credere."},
{"q":"La nascita di Nelson Mandela","risposta":1918,"curiosita":"Nelson Mandela nacque il 18 luglio 1918. Trascorse 27 anni in prigione. Diventò presidente del Sudafrica nel 1994 all'età di 75 anni."},
{"q":"La nascita di Pablo Picasso","risposta":1881,"curiosita":"Picasso nacque il 25 ottobre 1881 a Málaga. Il suo nome completo aveva 23 parole. Fondò il Cubismo insieme a Georges Braque intorno al 1907."},
{"q":"La scoperta della struttura del DNA (Watson e Crick)","risposta":1953,"curiosita":"Watson e Crick pubblicarono la struttura del DNA il 25 aprile 1953. Le loro ricerche si basavano crucialmente sulla Foto 51 di Rosalind Franklin, che non ricevette mai il Nobel."},
{"q":"La nascita di Confucio","risposta":-551,"curiosita":"Confucio nacque nel 551 a.C. in Cina. Le sue filosofie su etica, governo e relazioni sociali influenzano ancora oggi la cultura dell'Asia orientale."},
{"q":"La nascita di Alessandro Magno","risposta":-356,"curiosita":"Alessandro nacque nel 356 a.C. a Pella, Macedonia. Conquistò un impero vasto quanto tutta l'Europa in soli 13 anni. Morì a 32 anni — probabilmente di febbre tifoide."},
{"q":"La nascita di Cristoforo Colombo","risposta":1451,"curiosita":"Colombo nacque nel 1451 a Genova. Morì nel 1506 convinto di aver raggiunto l'Asia. Il continente che scoprì fu chiamato America da un altro esploratore, Amerigo Vespucci."},
{"q":"La Riforma Protestante di Lutero (inizio)","risposta":1517,"curiosita":"Il 31 ottobre 1517 Martin Lutero affisse le sue 95 tesi al portone della chiesa di Wittenberg. Diede inizio alla Riforma che spaccò la Chiesa cristiana in Europa."},
{"q":"La nascita di Aristotele","risposta":-384,"curiosita":"Aristotele nacque nel 384 a.C. a Stagira. Fu allievo di Platone e maestro di Alessandro Magno. Fondò la logica formale e scrisse su fisica, biologia, politica, poetica."},
{"q":"La nascita di Platone","risposta":-428,"curiosita":"Platone nacque nel 428 a.C. ad Atene. Fu allievo di Socrate. Fondò l'Accademia di Atene — la prima istituzione di istruzione superiore del mondo occidentale."},
{"q":"La nascita di Socrate","risposta":-470,"curiosita":"Socrate nacque nel 470 a.C. ad Atene. Non scrisse nulla — tutto ciò che sappiamo di lui viene da Platone e Senofonte. Fu condannato a morte nel 399 a.C. bevendo la cicuta."},
{"q":"La nascita di Omero (stima)","risposta":-800,"curiosita":"Omero visse probabilmente intorno all'800 a.C. Iliade e Odissea sono attribuiti a lui. Alcuni studiosi credono fossero opera di più autori raccolte sotto un unico nome."},
{"q":"La nascita di Dante Alighieri","risposta":1265,"curiosita":"Dante nacque nel maggio 1265 a Firenze. Fu esiliato dalla sua città nel 1302 — non ci tornò mai più. Scrisse la Divina Commedia durante l'esilio."},
{"q":"La pubblicazione del Don Chisciotte di Cervantes","risposta":1605,"curiosita":"Don Chisciotte fu pubblicato nel 1605. È considerato il primo romanzo moderno ed è uno dei libri più tradotti al mondo."},
{"q":"La nascita di Benito Mussolini","risposta":1883,"curiosita":"Mussolini nacque il 29 luglio 1883 a Predappio. Da giovane era socialista e giornalista. Fondò il fascismo nel 1919 e divenne dittatore d'Italia nel 1925."},
{"q":"La nascita di Mahatma Gandhi","risposta":1869,"curiosita":"Gandhi nacque il 2 ottobre 1869 in India. La sua filosofia della nonviolenza (ahimsa) ispirò movimenti per i diritti civili in tutto il mondo, incluso Martin Luther King."},
{"q":"La Grande Depressione (inizio)","risposta":1929,"curiosita":"Il 'Grande Crollo' di Wall Street il 29 ottobre 1929 innescò la Grande Depressione. Entro il 1933 un americano su quattro era disoccupato."},
{"q":"La nascita di Thomas Edison","risposta":1847,"curiosita":"Edison nacque l'11 febbraio 1847. Registrò 1.093 brevetti — un record. La sua rivalità con Tesla sulla corrente elettrica fu epica e spietata."},
{"q":"La nascita di Charles Chaplin","risposta":1889,"curiosita":"Chaplin nacque il 16 aprile 1889 a Londra in povertà estrema. Creò il personaggio di Charlot, il vagabondo con bombetta e bastone, che lo rese la star del cinema muto."},
{"q":"La fondazione dell'Impero Romano","risposta":-27,"curiosita":"Ottaviano divenne il primo imperatore romano con il titolo di Augusto nel 27 a.C. L'Impero Romano durò in Occidente fino al 476 d.C. — oltre 500 anni."},
{"q":"La fine delle Crociate","risposta":1291,"curiosita":"La caduta di Acri nel 1291 segnò la fine delle Crociate in Terra Santa. I cristiani persero definitivamente il controllo di Gerusalemme, conquistata nel 1099."},
{"q":"La nascita di Friedrich Nietzsche","risposta":1844,"curiosita":"Nietzsche nacque il 15 ottobre 1844. Scrisse la prima parte di 'Così parlò Zarathustra' in una decina di giorni. Secondo il racconto tradizionale, crollò nel 1889 a Torino abbracciando un cavallo."},
{"q":"La pubblicazione della prima edizione di Harry Potter","risposta":1997,"curiosita":"Harry Potter e la pietra filosofale fu pubblicato il 26 giugno 1997 dalla Bloomsbury. J.K. Rowling era una madre single che scriveva nei bar di Edimburgo."},
{"q":"L'invenzione della radio da parte di Marconi","risposta":1895,"curiosita":"Guglielmo Marconi ottenne il brevetto per la radio nel 1895. Nel 1901 trasmise il primo segnale attraverso l'Atlantico. Vinse il Nobel per la Fisica nel 1909."},
{"q":"La nascita di Vincent van Gogh","risposta":1853,"curiosita":"Van Gogh nacque il 30 marzo 1853 in Olanda. Vendette solo un quadro in vita. Si tagliò il lobo dell'orecchio nel 1888. Oggi i suoi quadri valgono decine di milioni."},
{"q":"La nascita di Puccini","risposta":1858,"curiosita":"Giacomo Puccini nacque il 22 dicembre 1858 a Lucca. Bohème, Tosca, Madama Butterfly e Turandot sono le sue opere più celebrate. Morì nel 1924 lasciando Turandot incompiuta."},
{"q":"La fondazione della Croce Rossa","risposta":1863,"curiosita":"La Croce Rossa fu fondata nel 1863 da Henry Dunant dopo aver assistito alla battaglia di Solferino nel 1859. Oggi è presente in quasi tutti i paesi del mondo."},
{"q":"La nascita di Verdi","risposta":1813,"curiosita":"Giuseppe Verdi nacque il 10 ottobre 1813 a Le Roncole. Rigoletto, Traviata, Otello e Aida sono solo alcune delle sue 28 opere. Il suo nome divenne un acronimo per Vittorio Emanuele Re D'Italia."},
{"q":"La nascita di Beethoven","risposta":1770,"curiosita":"Beethoven nacque il 17 dicembre 1770 a Bonn. Iniziò a perdere l'udito a 28 anni e compose alcune delle sue opere più grandi quando era completamente sordo."},
{"q":"La nascita di Johann Sebastian Bach","risposta":1685,"curiosita":"Bach nacque il 31 marzo 1685. Ebbe 20 figli. Morì nel 1750 quasi dimenticato. Fu riscoperto grazie a Mendelssohn nel 1829 con una storica esecuzione della Passione di San Matteo."},
{"q":"La Battaglia di Waterloo","risposta":1815,"curiosita":"La Battaglia di Waterloo il 18 giugno 1815 segnò la sconfitta definitiva di Napoleone, contro britannici e prussiani guidati da Wellington e Blücher."},
{"q":"La pubblicazione del Capitale di Marx","risposta":1867,"curiosita":"Il primo volume del Capitale fu pubblicato il 14 settembre 1867. Marx ne scrisse solo uno — gli altri due furono completati da Engels dopo la sua morte."},
{"q":"L'invenzione della macchina a vapore di Watt","risposta":1769,"curiosita":"James Watt brevettò la sua versione migliorata della macchina a vapore nel 1769. L'unità di misura della potenza, il Watt, prende il suo nome."},
{"q":"La nascita di Florence Nightingale","risposta":1820,"curiosita":"Florence Nightingale nacque il 12 maggio 1820 a Firenze — da cui il nome. Rivoluzionò l'assistenza sanitaria durante la Guerra di Crimea. È la fondatrice dell'infermieristica moderna."},
{"q":"La firma della Dichiarazione d'Indipendenza degli USA","risposta":1776,"curiosita":"La Dichiarazione fu approvata il 4 luglio 1776. Non tutti la firmarono quel giorno — molte firme furono aggiunte in agosto. La firma enorme di John Hancock è diventata leggendaria."},
{"q":"La nascita di Abraham Lincoln","risposta":1809,"curiosita":"Lincoln nacque il 12 febbraio 1809 in una capanna di tronchi in Kentucky. Fu il 16° presidente USA e abolì la schiavitù. Fu assassinato il 14 aprile 1865 al teatro Ford."},
{"q":"La fine della Guerra di Secessione Americana","risposta":1865,"curiosita":"La Guerra Civile americana finì il 9 aprile 1865 con la resa del generale Lee ad Appomattox. Causò oltre 620.000 morti — più di tutte le altre guerre americane messe insieme."},
{"q":"La nascita di Napoleone III","risposta":1808,"curiosita":"Napoleone III, nipote di Napoleone I, nacque nel 1808. Fu il primo presidente della Repubblica Francese e poi imperatore. Trasformò Parigi attraverso il barone Haussmann."},
{"q":"La scoperta dei raggi X da parte di Röntgen","risposta":1895,"curiosita":"Wilhelm Röntgen scoprì i raggi X il 8 novembre 1895. La prima radiografia fu della mano di sua moglie. Lei disse: 'Ho visto la mia morte'. Röntgen vinse il primo Nobel per la Fisica nel 1901."},
{"q":"La nascita di Copernico","risposta":1473,"curiosita":"Niccolò Copernico nacque il 19 febbraio 1473 in Polonia. Il suo modello eliocentrico del sistema solare fu pubblicato nel 1543, l'anno della sua morte."},
{"q":"La nascita di Archimede","risposta":-287,"curiosita":"Archimede nacque nel 287 a.C. a Siracusa. Scoprì il principio del galleggiamento nella vasca da bagno e corse nudo per le strade gridando 'Eureka!'. Almeno, così vuole la leggenda."},
{"q":"La nascita di Pitagora","risposta":-570,"curiosita":"Pitagora nacque intorno al 570 a.C. sull'isola di Samo. Fondò una comunità quasi religiosa in Crotone. Era vegetariano e credeva nella reincarnazione. Il teorema porta il suo nome ma era già noto ai babilonesi."},
{"q":"La fondazione dell'Accademia di Platone","risposta":-387,"curiosita":"Platone fondò l'Accademia di Atene intorno al 387 a.C. È considerata la prima università della storia occidentale. Sopravvisse quasi 900 anni fino alla chiusura nel 529 d.C."},
{"q":"La nascita di Marco Polo","risposta":1254,"curiosita":"Marco Polo nacque nel 1254 a Venezia. Il suo viaggio in Cina durò 24 anni. Il Milione, il resoconto dei suoi viaggi, fu dettato in prigione a Rustichello da Pisa. Molti non gli credettero."},
{"q":"La nascita di Cicerone","risposta":-106,"curiosita":"Marco Tullio Cicerone nacque nel 106 a.C. ad Arpino. Fu il più grande oratore romano. Scrisse circa 900 lettere che sopravvivono — la più vasta corrispondenza privata dell'antichità."},
{"q":"La nascita di Virgilio","risposta":-70,"curiosita":"Virgilio nacque nel 70 a.C. vicino a Mantova. L'Eneide, la sua opera più importante, fu scritta su commissione di Augusto. Morì prima di completarla e chiese che fosse distrutta."},
{"q":"Il Grande Incendio di Roma","risposta":64,"curiosita":"Il Grande Incendio di Roma del 64 d.C. bruciò per sei giorni. Nerone fu accusato di averlo appiccato — probabilmente ingiustamente. Usò i cristiani come capri espiatori."},
{"q":"La nascita di Jules Verne","risposta":1828,"curiosita":"Jules Verne nacque l'8 febbraio 1828 a Nantes. Scrisse 'Ventimila leghe sotto i mari', 'Il giro del mondo in 80 giorni' e 'Viaggio al centro della Terra'. Immaginò sottomarini e viaggi spaziali molto prima che esistessero."},
{"q":"La nascita di Victor Hugo","risposta":1802,"curiosita":"Hugo nacque il 26 febbraio 1802 a Besançon. I Miserabili e Notre-Dame de Paris sono le sue opere più celebri. Morì nel 1885 — al suo funerale parteciparono 2 milioni di persone."},
{"q":"La nascita di Alessandro Volta","risposta":1745,"curiosita":"Volta nacque il 18 febbraio 1745 a Como. Inventò la pila elettrica nel 1800 — la prima fonte di corrente continua. L'unità di misura della tensione, il Volt, porta il suo nome."},
{"q":"La nascita di Amerigo Vespucci","risposta":1454,"curiosita":"Vespucci nacque il 9 marzo 1454 a Firenze. Esplorò le coste del Sud America e capì che era un continente nuovo, non l'Asia. Il cartografo Waldseemüller chiamò il nuovo continente 'America' in suo onore."},
{"q":"La nascita di Raffaello","risposta":1483,"curiosita":"Raffaello Sanzio nacque il 6 aprile 1483 ad Urbino. Morì esattamente il giorno del suo compleanno, il 6 aprile 1520, a soli 37 anni. La sua opera più celebre è La Scuola di Atene."},
{"q":"La nascita di Caravaggio","risposta":1571,"curiosita":"Michelangelo Merisi da Caravaggio nacque nel 1571 a Milano. Rivoluzionò la pittura con il chiaroscuro estremo. Uccise un uomo in una rissa nel 1606 e visse come fuggiasco fino alla morte."},
{"q":"La nascita di Tiziano","risposta":1488,"curiosita":"Tiziano Vecellio nacque intorno al 1488 a Pieve di Cadore. Morì nel 1576 all'età di circa 88 anni — eccezionale per l'epoca. Era il pittore preferito di Carlo V d'Asburgo."},
{"q":"La nascita di Machiavelli","risposta":1469,"curiosita":"Niccolò Machiavelli nacque il 3 maggio 1469 a Firenze. Scrisse Il Principe nel 1513 mentre era in esilio. Il termine 'machiavellico' è entrato in tutte le lingue per indicare la politica senza scrupoli."},
{"q":"La fondazione di Costantinopoli","risposta":330,"curiosita":"Costantino I fondò Costantinopoli il 11 maggio 330 d.C. sull'antico sito di Bisanzio. Fu la capitale dell'Impero Bizantino per oltre 1.000 anni fino al 1453."},
{"q":"L'editto di Milano (libertà di culto nell'Impero Romano)","risposta":313,"curiosita":"Nel 313 d.C. Costantino I emanò l'Editto di Milano, garantendo la libertà religiosa nell'Impero Romano. Segnò la fine delle persecuzioni dei cristiani."},
{"q":"La nascita di Rainer Maria Rilke","risposta":1875,"curiosita":"Rilke nacque il 4 dicembre 1875 a Praga. Le Elegie Duinesi e le Lettere a un giovane poeta sono le sue opere più amate. Morì nel 1926 di leucemia, forse causata da una spina di rosa."},
{"q":"Il Grande Terremoto di Lisbona","risposta":1755,"curiosita":"Il 1° novembre 1755 un terremoto devastò Lisbona. Lo tsunami e gli incendi uccisero 60.000 persone. Voltaire scrisse Candide ispirandosi a questa catastrofe."},
{"q":"La nascita di Erasmo da Rotterdam","risposta":1469,"curiosita":"Erasmo nacque il 28 ottobre 1469 a Rotterdam. Fu il principale intellettuale dell'Umanesimo nordeuropeo. Il programma universitario che porta il suo nome ha permesso a milioni di studenti di studiare all'estero."},
{"q":"La nascita di Thomas More (Tommaso Moro)","risposta":1478,"curiosita":"Tommaso Moro nacque il 7 febbraio 1478 a Londra. Scrisse 'Utopia' nel 1516. Fu decapitato da Enrico VIII nel 1535 per essersi rifiutato di riconoscerlo capo della Chiesa d'Inghilterra."},
{"q":"La pubblicazione del Systema Naturae di Linneo","risposta":1735,"curiosita":"Carlo Linneo pubblicò il Systema Naturae nel 1735, introducendo la nomenclatura binomiale. Ogni essere vivente oggi ha un nome scientifico basato sul suo sistema."},
{"q":"La nascita di Adam Smith","risposta":1723,"curiosita":"Adam Smith nacque il 16 giugno 1723 a Kirkcaldy, Scozia. La Ricchezza delle Nazioni (1776) è il fondamento dell'economia moderna liberale. Il concetto di 'mano invisibile' del mercato è suo."},
{"q":"La nascita di Immanuel Kant","risposta":1724,"curiosita":"Kant nacque il 22 aprile 1724 a Königsberg. Non si allontanò mai dalla sua città. Era talmente puntuale che i cittadini regolavano gli orologi quando lo vedevano passare."},
{"q":"La nascita di René Descartes","risposta":1596,"curiosita":"Cartesio nacque il 31 marzo 1596 in Francia. 'Cogito ergo sum' — penso quindi sono — è la sua frase più celebre. Fondò la geometria analitica (il piano cartesiano porta il suo nome)."},
{"q":"La nascita di Voltaire","risposta":1694,"curiosita":"Voltaire nacque il 21 novembre 1694 a Parigi. Beveva 40-50 tazze di caffè al giorno. Fu incarcerato alla Bastiglia due volte. Il suo Candide è uno dei romanzi filosofici più letti della storia."},
{"q":"La nascita di Jean-Jacques Rousseau","risposta":1712,"curiosita":"Rousseau nacque il 28 giugno 1712 a Ginevra. Le sue idee sul contratto sociale influenzarono profondamente la Rivoluzione Francese e la filosofia politica moderna."},
{"q":"La costruzione del Partenone (inizio)","risposta":-447,"curiosita":"Il Partenone fu costruito tra il 447 e il 438 a.C. sull'Acropoli di Atene. Fu ordinato da Pericle. Rimase intatto per 2.000 anni fino al 1687, quando un'esplosione lo danneggiò gravemente."},
{"q":"La nascita di Ippocrate","risposta":-460,"curiosita":"Ippocrate nacque intorno al 460 a.C. sull'isola di Cos. È considerato il padre della medicina. Il Giuramento di Ippocrate è ancora il fondamento etico della professione medica."},
{"q":"La battaglia delle Termopili","risposta":-480,"curiosita":"Nel 480 a.C. 300 spartani guidati da Leonida resistettero per tre giorni all'esercito persiano di Serse. Perirono tutti. La loro resistenza permise alla Grecia di organizzare la controffensiva."},
{"q":"La fondazione di Cartagine (stima)","risposta":-814,"curiosita":"Cartagine fu fondata intorno all'814 a.C. da coloni fenici provenienti da Tiro. Divenne la grande rivale di Roma nel Mediterraneo. Annibale partì da qui per attraversare le Alpi."},
{"q":"La nascita di Annibale","risposta":-247,"curiosita":"Annibale Barca nacque nel 247 a.C. a Cartagine. Attraversò le Alpi con 37 elefanti nel 218 a.C. e inflisse a Roma alcune delle peggiori sconfitte della sua storia. Non riuscì mai a conquistare Roma."},
{"q":"Il Sacco di Roma da parte dei Visigoti","risposta":410,"curiosita":"Nel 410 d.C. i Visigoti guidati da Alarico saccheggiarono Roma per tre giorni. Era la prima volta che Roma veniva saccheggiata in 800 anni. Sant'Agostino scrisse 'La Città di Dio' in risposta."},
{"q":"La scoperta dell'America del Sud da Vespucci","risposta":1499,"curiosita":"Amerigo Vespucci esplorò le coste del Sud America nel 1499-1500. Capì che era un continente sconosciuto — e non l'Asia. Per questo il continente porta il suo nome."},
{"q":"La nascita di Francisco de Goya","risposta":1746,"curiosita":"Goya nacque il 30 marzo 1746 a Fuendetodos, Spagna. Pittore di corte di Carlo IV, divenne sordo nel 1792 e le sue opere divennero sempre più oscure. Le 'Pitture nere' sono tra le più inquietanti dell'arte occidentale."},
{"q":"La nascita di Giacomo Leopardi","risposta":1798,"curiosita":"Leopardi nacque il 29 giugno 1798 a Recanati. Il suo pessimismo cosmico lo rese il più grande poeta italiano del Romanticismo. L'Infinito è la sua poesia più celebre."},
{"q":"La fondazione dell'UNESCO","risposta":1945,"curiosita":"L'UNESCO fu fondata il 16 novembre 1945 a Londra. La sua missione è promuovere pace e sicurezza attraverso educazione, scienza e cultura. Ha 195 stati membri."},
{"q":"La pubblicazione della Critica della Ragion Pura di Kant","risposta":1781,"curiosita":"Kant pubblicò la Critica della Ragion Pura nel 1781, dopo 11 anni di riflessione. È considerata una delle opere filosofiche più importanti della storia occidentale."},
{"q":"La fondazione della FIFA","risposta":1904,"curiosita":"La FIFA fu fondata il 21 maggio 1904 a Parigi da 7 paesi europei. Oggi conta 211 federazioni nazionali — più degli stati membri dell'ONU."},
{"q":"Il primo Campionato del Mondo di Calcio","risposta":1930,"curiosita":"Il primo Mondiale si tenne in Uruguay nel 1930. L'Uruguay vinse il torneo in casa. Solo 13 squadre parteciparono — le europee quasi tutte rifiutarono per la lunga traversata in nave."},
{"q":"La nascita di Pelé","risposta":1940,"curiosita":"Pelé nacque il 23 ottobre 1940 a Três Corações, Brasile. Segnò 1.281 gol in carriera. Vinse tre Mondiali (1958, 1962, 1970) — è l'unico calciatore nella storia a riuscirci."},
{"q":"La nascita di Muhammad Ali","risposta":1942,"curiosita":"Muhammad Ali nacque il 17 gennaio 1942 a Louisville, Kentucky. Divenne campione del mondo dei pesi massimi a 22 anni. Si rifiutò di andare in Vietnam e fu privato del titolo per tre anni."},
{"q":"La nascita di Ayrton Senna","risposta":1960,"curiosita":"Senna nacque il 21 marzo 1960 a San Paolo. Vinse 3 titoli mondiali di F1. Morì il 1° maggio 1994 durante il Gran Premio di San Marino a Imola: da allora la sicurezza in F1 è migliorata enormemente."},
{"q":"Il primo Mondiale di Formula 1","risposta":1950,"curiosita":"Il primo Campionato del Mondo di Formula 1 si tenne nel 1950. Nino Farina con Alfa Romeo fu il primo campione. Il Gran Premio di Gran Bretagna a Silverstone fu la prima gara."},
{"q":"La nascita di Roger Federer","risposta":1981,"curiosita":"Federer nacque l'8 agosto 1981 a Basilea. Vinse 20 titoli del Grande Slam. È considerato da molti il più grande tennista di tutti i tempi."},
{"q":"La prima edizione dei Giochi Olimpici moderni","risposta":1896,"curiosita":"Le prime Olimpiadi moderne si tennero ad Atene nel 1896. Parteciparono 241 atleti da 14 paesi. Le donne non potevano competere — ci riuscirono per la prima volta nel 1900 a Parigi."},
{"q":"La fondazione della Scuderia Ferrari","risposta":1929,"curiosita":"Enzo Ferrari fondò la Scuderia Ferrari a Modena nel 1929 come squadra corse per le Alfa Romeo. La prima auto con il nome Ferrari uscì nel 1947."},
{"q":"La nascita di Enzo Ferrari","risposta":1898,"curiosita":"Enzo Ferrari nacque il 18 febbraio 1898 a Modena. Costruì un impero automobilistico partendo dalla passione per le gare. Morì nel 1988 a 90 anni."},
{"q":"La nascita di Michael Jackson","risposta":1958,"curiosita":"Michael Jackson nacque il 29 agosto 1958 a Gary, Indiana. Thriller (1982) è l'album più venduto della storia. Il suo moonwalk fu eseguito per la prima volta in TV il 25 marzo 1983."},
{"q":"La nascita di Madonna","risposta":1958,"curiosita":"Madonna nacque il 16 agosto 1958 a Bay City, Michigan. È la cantante solista femminile con più vendite nella storia — oltre 300 milioni di dischi."},
{"q":"La nascita di David Bowie","risposta":1947,"curiosita":"Bowie nacque l'8 gennaio 1947 a Londra. Vendette oltre 100 milioni di dischi. I suoi occhi sembravano di due colori diversi per l'anisocoria: una pupilla rimasta dilatata dopo un pugno ricevuto da ragazzo."},
{"q":"La nascita di Freddie Mercury","risposta":1946,"curiosita":"Freddie Mercury nacque il 5 settembre 1946 a Zanzibar. Il suo vero nome era Farrokh Bulsara. Bohemian Rhapsody rimane una delle canzoni più ascoltate di tutti i tempi."},
{"q":"La nascita di Elvis Presley","risposta":1935,"curiosita":"Elvis nacque l'8 gennaio 1935 a Tupelo, Mississippi. Vendette oltre 500 milioni di dischi. È ancora uno degli artisti più redditizi al mondo — decenni dopo la sua morte nel 1977."},
{"q":"La nascita di John Lennon","risposta":1940,"curiosita":"Lennon nacque il 9 ottobre 1940 a Liverpool. Fondò i Beatles nel 1960. Fu assassinato l'8 dicembre 1980 davanti al Dakota Building di New York."},
{"q":"La prima trasmissione radiofonica pubblica","risposta":1920,"curiosita":"La prima trasmissione radiofonica pubblica regolare avvenne il 2 novembre 1920 dalla stazione KDKA di Pittsburgh. Trasmise i risultati delle elezioni presidenziali americane."},
{"q":"L'invenzione del World Wide Web da parte di Berners-Lee","risposta":1989,"curiosita":"Tim Berners-Lee propose il World Wide Web nel 1989 lavorando al CERN di Ginevra. Il primo sito web andò online il 6 agosto 1991. Berners-Lee non lo brevettò mai — lo regalò al mondo."},
{"q":"La nascita di Stephen Hawking","risposta":1942,"curiosita":"Hawking nacque l'8 gennaio 1942 a Oxford — esattamente 300 anni dopo la morte di Galileo. Fu diagnosticato con la SLA a 21 anni e i medici gli diedero 2 anni di vita. Ne visse altri 55."},
{"q":"La pubblicazione di '1984' di George Orwell","risposta":1949,"curiosita":"George Orwell pubblicò '1984' l'8 giugno 1949 — pochi mesi prima di morire. Introdusse concetti come Grande Fratello, bispensiero e neolingua. È uno dei romanzi più venduti di tutti i tempi."},
{"q":"La nascita di Woody Allen","risposta":1935,"curiosita":"Woody Allen nacque il 1° dicembre 1935 a Brooklyn. Ha diretto un film all'anno per quasi 50 anni consecutivi. Vinse 4 premi Oscar."},
{"q":"La fondazione di Netflix","risposta":1997,"curiosita":"Reed Hastings e Marc Randolph fondarono Netflix il 29 agosto 1997. Iniziò come servizio di noleggio DVD per posta. Il passaggio allo streaming avvenne nel 2007."}];
var ANNO_GIUSTO_DATA_EN=[{"q":"The fall of the Berlin Wall","risposta":1989,"curiosita":"On 9 November 1989 thousands of Berliners began tearing down the wall that had divided the city since 1961. It was the symbolic end of the Cold War."},
{"q":"The first Moon landing","risposta":1969,"curiosita":"On 20 July 1969 Neil Armstrong and Buzz Aldrin landed with Apollo 11. Armstrong said: 'That's one small step for man, one giant leap for mankind'."},
{"q":"The birth of the internet (ARPANET)","risposta":1969,"curiosita":"On 29 October 1969 the first message was sent over ARPANET: 'lo'. The system crashed after two letters, but the network was born."},
{"q":"Gutenberg's invention of movable-type printing","risposta":1450,"curiosita":"Around 1450 Gutenberg invented movable-type printing. The Gutenberg Bible was the first major book printed in Europe — about 180 copies."},
{"q":"Columbus's arrival in America","risposta":1492,"curiosita":"On 12 October 1492 Columbus sighted land in the Caribbean. He thought he had reached Asia — he died without knowing he had found a new continent."},
{"q":"The start of the First Industrial Revolution","risposta":1760,"curiosita":"The Industrial Revolution began in England around 1760, with innovations such as the steam engine improved by James Watt. It changed human work forever."},
{"q":"The start of the French Revolution","risposta":1789,"curiosita":"On 14 July 1789 the Bastille fell. The French Revolution gave the world the ideals of liberty, equality and fraternity."},
{"q":"The birth of Leonardo da Vinci","risposta":1452,"curiosita":"Leonardo was born on 15 April 1452 in Anchiano, near Vinci. Painter, scientist, engineer: the most complete genius of the Renaissance."},
{"q":"The death of Napoleon Bonaparte","risposta":1821,"curiosita":"Napoleon died on 5 May 1821 in exile on the island of Saint Helena, aged 51. People still debate whether he was poisoned with arsenic."},
{"q":"The founding of Rome (according to tradition)","risposta":-753,"curiosita":"According to tradition, Romulus founded Rome in 753 BC. In reality the first settlements in the area date back to around 1000 BC."},
{"q":"The start of World War I","risposta":1914,"curiosita":"On 28 June 1914 Archduke Franz Ferdinand was assassinated in Sarajevo. Four years later the war had caused over 20 million deaths."},
{"q":"The end of World War II","risposta":1945,"curiosita":"On 2 September 1945 Japan signed its surrender after the atomic bombs on Hiroshima and Nagasaki. 70-85 million people died in the conflict."},
{"q":"The launch of the first iPhone","risposta":2007,"curiosita":"Steve Jobs unveiled the first iPhone on 9 January 2007, describing it as 'an iPod, a phone and an internet communicator'. Nobody immediately grasped how much it would change."},
{"q":"The launch of Facebook","risposta":2004,"curiosita":"Mark Zuckerberg launched Facebook on 4 February 2004 from Harvard. It was originally called 'TheFacebook' and was only for university students."},
{"q":"The birth of YouTube","risposta":2005,"curiosita":"YouTube was founded on 14 February 2005 by three former PayPal employees. The first video was called 'Me at the zoo' and it's still online."},
{"q":"The founding of Google","risposta":1998,"curiosita":"Larry Page and Sergey Brin founded Google on 4 September 1998 in a garage in Menlo Park. The name comes from 'googol', 10 to the power of 100."},
{"q":"The first tweet on Twitter","risposta":2006,"curiosita":"Jack Dorsey posted the first tweet on 21 March 2006: 'just setting up my twttr'. The platform launched to the public in July that year."},
{"q":"The fall of the Western Roman Empire","risposta":476,"curiosita":"In AD 476 Odoacer deposed the last Western Roman emperor, Romulus Augustulus. It conventionally marks the end of antiquity and the start of the Middle Ages."},
{"q":"The birth of William Shakespeare","risposta":1564,"curiosita":"Shakespeare was born in April 1564 in Stratford-upon-Avon. He wrote around 37 plays and 154 sonnets, and is still the most performed playwright in the world."},
{"q":"The publication of Einstein's theory of relativity","risposta":1905,"curiosita":"In 1905 Einstein published four revolutionary papers, including special relativity and E=mc². It's known as his 'miracle year'."},
{"q":"The start of construction of the Great Wall of China","risposta":-221,"curiosita":"The Great Wall began to be unified in 221 BC under Emperor Qin Shi Huang. Contrary to legend, it isn't visible to the naked eye from space."},
{"q":"The birth of Isaac Newton","risposta":1643,"curiosita":"Newton was born on 4 January 1643 in England. The legend of the falling apple supposedly led him to the theory of universal gravitation."},
{"q":"The death of Julius Caesar","risposta":-44,"curiosita":"Julius Caesar was assassinated on the Ides of March (15 March) 44 BC. He was stabbed 23 times by senators led by Brutus and Cassius."},
{"q":"The opening of the Colosseum","risposta":80,"curiosita":"The Colosseum was inaugurated in AD 80 by Emperor Titus with 100 days of games. It could hold up to 80,000 spectators."},
{"q":"The Russian October Revolution","risposta":1917,"curiosita":"The October Revolution of 1917 brought Lenin's Bolsheviks to power. It created the first communist state in history, which lasted until 1991."},
{"q":"Bell's invention of the telephone","risposta":1876,"curiosita":"Alexander Graham Bell patented the telephone on 7 March 1876. The first sentence transmitted was: 'Mr Watson, come here, I want to see you'."},
{"q":"The birth of Mozart","risposta":1756,"curiosita":"Wolfgang Amadeus Mozart was born on 27 January 1756 in Salzburg. He composed his first symphony at 8 and died at 35, leaving over 600 compositions."},
{"q":"The birth of Michelangelo","risposta":1475,"curiosita":"Michelangelo was born on 6 March 1475. He painted the Sistine Chapel ceiling between 1508 and 1512, working for four years on high scaffolding."},
{"q":"The completion of Dante's Divine Comedy","risposta":1321,"curiosita":"Dante completed the Divine Comedy shortly before he died in 1321. It's considered the greatest work of Italian literature and one of the most important in the world."},
{"q":"The end of apartheid in South Africa","risposta":1994,"curiosita":"In 1994 South Africa held its first democratic elections. Nelson Mandela, after 27 years in prison, became the country's first black president."},
{"q":"The launch of Sputnik (the first artificial satellite)","risposta":1957,"curiosita":"On 4 October 1957 the USSR launched Sputnik, the first artificial satellite in history. It was the size of a beach ball and only transmitted a radio beep."},
{"q":"The founding of the United Nations","risposta":1945,"curiosita":"The United Nations was founded on 24 October 1945 by 51 countries after World War II. Today it has 193 member states."},
{"q":"The sealing of Magna Carta","risposta":1215,"curiosita":"Magna Carta was sealed on 15 June 1215 by King John of England. It's considered a foundation of modern constitutional law."},
{"q":"The birth of Albert Einstein","risposta":1879,"curiosita":"Einstein was born on 14 March 1879 in Ulm, Germany. He wasn't an outstanding pupil — but the myth that he failed maths is false."},
{"q":"The birth of Galileo Galilei","risposta":1564,"curiosita":"Galileo was born on 15 February 1564 in Pisa. He improved the telescope, pointed it at the sky and argued that the Earth goes around the Sun — for which he was tried by the Inquisition."},
{"q":"The founding of the European Union (Maastricht Treaty)","risposta":1993,"curiosita":"The Maastricht Treaty came into force on 1 November 1993, formally creating the European Union. It paved the way for the euro and free movement."},
{"q":"The launch of Amazon","risposta":1994,"curiosita":"Jeff Bezos founded Amazon on 5 July 1994 in a Seattle garage. At first it only sold books. Today it's one of the largest marketplaces in the world."},
{"q":"The birth of Cleopatra","risposta":-69,"curiosita":"Cleopatra was born in 69 BC. She was of Macedonian Greek descent, not Egyptian. She was the last Ptolemaic queen and reportedly spoke 9 languages."},
{"q":"The building of the Great Pyramid of Giza","risposta":-2560,"curiosita":"The Great Pyramid of Giza was built around 2560 BC for the pharaoh Khufu. For over 3,800 years it was the tallest structure in the world."},
{"q":"The birth of Jesus (historical estimate)","risposta":-4,"curiosita":"Ironically, Jesus was probably born between 6 and 4 BC. The calendar error was made by the monk Dionysius Exiguus in the 6th century."},
{"q":"The founding of Venice","risposta":421,"curiosita":"Venice was traditionally founded on 25 March AD 421. It was built on 118 islands linked by over 400 bridges, and for centuries it was the commercial power of the Mediterranean."},
{"q":"The birth of Napoleon Bonaparte","risposta":1769,"curiosita":"Napoleon was born on 15 August 1769 in Ajaccio, Corsica, just after France took the island. And he wasn't short: about 1.69 m — average for the time."},
{"q":"The publication of Darwin's On the Origin of Species","risposta":1859,"curiosita":"Darwin published On the Origin of Species on 24 November 1859. The 1,250 copies of the first edition sold out on the first day."},
{"q":"The birth of Karl Marx","risposta":1818,"curiosita":"Karl Marx was born on 5 May 1818 in Trier. The Communist Manifesto, written with Engels, was published in 1848."},
{"q":"The arrival of the Black Death in Europe","risposta":1347,"curiosita":"The Black Death reached Europe in 1347 and in five years killed between 30% and 60% of Europe's population — about 25 million people."},
{"q":"The birth of Muhammad","risposta":570,"curiosita":"Muhammad was born around AD 570 in Mecca. He received his first revelations in 610. Islam is today one of the fastest-growing religions in the world."},
{"q":"The discovery of penicillin","risposta":1928,"curiosita":"Alexander Fleming discovered penicillin by chance on 3 September 1928, noticing a mould had killed the bacteria in a Petri dish. It saved millions of lives."},
{"q":"The end of World War II in Europe (V-E Day)","risposta":1945,"curiosita":"On 8 May 1945 Germany's unconditional surrender took effect. Spontaneous celebrations broke out across Europe. The war in the Pacific would end in August."},
{"q":"The birth of Steve Jobs","risposta":1955,"curiosita":"Steve Jobs was born on 24 February 1955 and was adopted at birth. He founded Apple in 1976 with Steve Wozniak in a garage, and revolutionised computers, music, phones and animation."},
{"q":"The assassination of John F. Kennedy","risposta":1963,"curiosita":"JFK was assassinated on 22 November 1963 in Dallas during a motorcade. Lee Harvey Oswald was arrested but shot dead two days later by Jack Ruby."},
{"q":"The start of the First Crusade","risposta":1096,"curiosita":"The First Crusade was proclaimed by Pope Urban II in 1095. The crusaders set off in 1096 and took Jerusalem in 1099 after a bloody siege."},
{"q":"The birth of Charles Darwin","risposta":1809,"curiosita":"Darwin was born on 12 February 1809 — the same day as Abraham Lincoln. He studied medicine, then theology, before becoming history's most revolutionary naturalist."},
{"q":"The sinking of the Titanic","risposta":1912,"curiosita":"The Titanic sank on 15 April 1912 on its maiden voyage. About 1,500 people died. The wreck was only found at the bottom of the Atlantic in 1985."},
{"q":"The birth of Adolf Hitler","risposta":1889,"curiosita":"Hitler was born on 20 April 1889 in Austria. He was rejected twice by the Vienna Academy of Fine Arts — a humiliation that deeply marked him."},
{"q":"The end of the Soviet Union","risposta":1991,"curiosita":"On 25 December 1991 Gorbachev resigned and the USSR officially ceased to exist, splitting into 15 independent states. The Cold War was over."},
{"q":"The first ascent of Everest","risposta":1953,"curiosita":"On 29 May 1953 Edmund Hillary and Tenzing Norgay were the first to reach the summit of Everest (8,849 m). The news reached London on the day of Queen Elizabeth II's coronation."},
{"q":"Edison's light bulb","risposta":1879,"curiosita":"Edison patented his light bulb in 1879-80. Many others had worked on it before; his achievement was making it practical and profitable."},
{"q":"The founding of Apple","risposta":1976,"curiosita":"Apple was founded on 1 April 1976 by Steve Jobs, Steve Wozniak and Ronald Wayne. Wayne sold his share for 800 dollars — today it would be worth billions."},
{"q":"The birth of Winston Churchill","risposta":1874,"curiosita":"Churchill was born on 30 November 1874. He won the Nobel Prize in Literature in 1953 — not Peace. He was a keen painter and wrote over 40 books."},
{"q":"The invention of cinema (the Lumière brothers)","risposta":1895,"curiosita":"On 28 December 1895 the Lumière brothers held the first public film screening in Paris. Legend has it that some viewers fled when they saw a train arriving on screen."},
{"q":"The birth of Frida Kahlo","risposta":1907,"curiosita":"Frida Kahlo was born on 6 July 1907 in Coyoacán, Mexico. After a serious accident at 18 she began to paint. Her life was an inseparable blend of art and pain."},
{"q":"The first regular public TV service (BBC)","risposta":1936,"curiosita":"The BBC launched the first regular public television service on 2 November 1936, broadcasting 2 hours a day. TV was suspended during World War II."},
{"q":"The approval of the Italian Constitution","risposta":1947,"curiosita":"The Italian Constitution was approved on 22 December 1947 and came into force on 1 January 1948. It was written by the Constituent Assembly after the fall of fascism."},
{"q":"The birth of Sigmund Freud","risposta":1856,"curiosita":"Freud was born on 6 May 1856 in Freiberg. He founded psychoanalysis. He smoked 20 cigars a day and kept going even after 33 operations for jaw cancer."},
{"q":"The first mobile phone prototype call","risposta":1973,"curiosita":"Motorola's Martin Cooper made the first call on a prototype mobile phone on 3 April 1973. The phone weighed about 1 kg and offered 30 minutes of talk time."},
{"q":"The birth of Nikola Tesla","risposta":1856,"curiosita":"Tesla was born on 10 July 1856 in present-day Croatia, to a Serbian family. He developed the alternating current system. He died poor and alone in a hotel room in 1943 — many of his patents had gone to Westinghouse."},
{"q":"The birth of Marie Curie","risposta":1867,"curiosita":"Marie Curie was born on 7 November 1867 in Warsaw. She was the first woman to win a Nobel Prize and the only person to win in two different sciences (Physics 1903, Chemistry 1911)."},
{"q":"The fall of Constantinople","risposta":1453,"curiosita":"On 29 May 1453 the Ottoman Turks of Mehmed II took Constantinople, ending the Byzantine Empire. It conventionally marks the end of the Middle Ages."},
{"q":"The start of the Council of Trent","risposta":1545,"curiosita":"The Council of Trent began in 1545 and lasted almost 20 years. It was the Catholic Church's response to Luther's Protestant Reformation."},
{"q":"The birth of Martin Luther King Jr.","risposta":1929,"curiosita":"MLK was born on 15 January 1929 in Atlanta. He delivered his 'I Have a Dream' speech on 28 August 1963 before 250,000 people in Washington."},
{"q":"The atomic bombing of Hiroshima","risposta":1945,"curiosita":"On 6 August 1945 the atomic bomb 'Little Boy' was dropped on Hiroshima. Some 80,000 people died within seconds; by the end of the year the toll reached 140,000."},
{"q":"The founding of Microsoft","risposta":1975,"curiosita":"Bill Gates and Paul Allen founded Microsoft on 4 April 1975 in Albuquerque, New Mexico. The name combines 'microcomputer' and 'software'."},
{"q":"The birth of Walt Disney","risposta":1901,"curiosita":"Walt Disney was born on 5 December 1901 in Chicago. He created Mickey Mouse in 1928. Snow White (1937) was Disney's first animated feature and a worldwide hit."},
{"q":"The Wright brothers' flight (first powered aeroplane)","risposta":1903,"curiosita":"On 17 December 1903 Orville Wright flew for 12 seconds at Kitty Hawk. Few newspapers reported it: for many it was too incredible to believe."},
{"q":"The birth of Nelson Mandela","risposta":1918,"curiosita":"Nelson Mandela was born on 18 July 1918. He spent 27 years in prison and became president of South Africa in 1994, aged 75."},
{"q":"The birth of Pablo Picasso","risposta":1881,"curiosita":"Picasso was born on 25 October 1881 in Málaga. His full name had over 20 parts. He founded Cubism with Georges Braque around 1907."},
{"q":"The discovery of DNA's structure (Watson and Crick)","risposta":1953,"curiosita":"Watson and Crick published the structure of DNA on 25 April 1953. Their work relied crucially on Rosalind Franklin's Photo 51 — she never received a Nobel."},
{"q":"The birth of Confucius","risposta":-551,"curiosita":"Confucius was born in 551 BC in China. His philosophy of ethics, government and social relationships still shapes East Asian culture today."},
{"q":"The birth of Alexander the Great","risposta":-356,"curiosita":"Alexander was born in 356 BC in Pella, Macedonia. In just 13 years he conquered a vast empire. He died at 32 — possibly of typhoid fever."},
{"q":"The birth of Christopher Columbus","risposta":1451,"curiosita":"Columbus was born in 1451 in Genoa. He died in 1506 convinced he had reached Asia. The continent he reached was named America after another explorer, Amerigo Vespucci."},
{"q":"The start of Luther's Protestant Reformation","risposta":1517,"curiosita":"On 31 October 1517 Martin Luther published his 95 Theses in Wittenberg. It began the Reformation that split Western Christianity."},
{"q":"The birth of Aristotle","risposta":-384,"curiosita":"Aristotle was born in 384 BC in Stagira. A pupil of Plato and teacher of Alexander the Great, he founded formal logic and wrote on physics, biology, politics and poetics."},
{"q":"The birth of Plato","risposta":-428,"curiosita":"Plato was born around 428 BC in Athens. A pupil of Socrates, he founded the Academy in Athens — the first institution of higher learning in the Western world."},
{"q":"The birth of Socrates","risposta":-470,"curiosita":"Socrates was born around 470 BC in Athens. He wrote nothing — everything we know comes from Plato and Xenophon. He was sentenced to death in 399 BC by drinking hemlock."},
{"q":"The life of Homer (estimate)","risposta":-800,"curiosita":"Homer probably lived around 800 BC. The Iliad and the Odyssey are attributed to him, though some scholars believe they were the work of several authors."},
{"q":"The birth of Dante Alighieri","risposta":1265,"curiosita":"Dante was born in May 1265 in Florence. He was exiled from his city in 1302 and never returned. He wrote the Divine Comedy in exile."},
{"q":"The publication of Cervantes's Don Quixote","risposta":1605,"curiosita":"Don Quixote was published in 1605. It's considered the first modern novel and is one of the most translated books in the world."},
{"q":"The birth of Benito Mussolini","risposta":1883,"curiosita":"Mussolini was born on 29 July 1883 in Predappio. As a young man he was a socialist and journalist. He founded fascism in 1919 and became dictator of Italy in 1925."},
{"q":"The birth of Mahatma Gandhi","risposta":1869,"curiosita":"Gandhi was born on 2 October 1869 in India. His philosophy of non-violence (ahimsa) inspired civil rights movements worldwide, including Martin Luther King."},
{"q":"The start of the Great Depression","risposta":1929,"curiosita":"The Wall Street Crash of 29 October 1929 triggered the Great Depression. By 1933 one American in four was unemployed."},
{"q":"The birth of Thomas Edison","risposta":1847,"curiosita":"Edison was born on 11 February 1847. He registered 1,093 patents — a record. His rivalry with Tesla over electric current was epic and ruthless."},
{"q":"The birth of Charlie Chaplin","risposta":1889,"curiosita":"Chaplin was born on 16 April 1889 in London into extreme poverty. He created the Tramp, with bowler hat and cane, which made him the star of silent cinema."},
{"q":"The founding of the Roman Empire","risposta":-27,"curiosita":"Octavian became the first Roman emperor with the title Augustus in 27 BC. The Empire lasted in the West until AD 476 — over 500 years."},
{"q":"The end of the Crusades","risposta":1291,"curiosita":"The fall of Acre in 1291 marked the end of the Crusades in the Holy Land. The Christians permanently lost the territory they had conquered in 1099."},
{"q":"The birth of Friedrich Nietzsche","risposta":1844,"curiosita":"Nietzsche was born on 15 October 1844. He wrote the first part of Thus Spoke Zarathustra in about ten days. According to the traditional account, he collapsed in Turin in 1889 while embracing a horse."},
{"q":"The publication of the first Harry Potter book","risposta":1997,"curiosita":"Harry Potter and the Philosopher's Stone was published on 26 June 1997 by Bloomsbury. J.K. Rowling was a single mother who wrote in Edinburgh cafés."},
{"q":"Marconi's invention of the radio","risposta":1895,"curiosita":"Guglielmo Marconi began his radio experiments in 1895. In 1901 he sent the first signal across the Atlantic. He won the Nobel Prize in Physics in 1909."},
{"q":"The birth of Vincent van Gogh","risposta":1853,"curiosita":"Van Gogh was born on 30 March 1853 in the Netherlands. He sold very few paintings in his lifetime and cut off part of his ear in 1888. Today his works are worth tens of millions."},
{"q":"The birth of Puccini","risposta":1858,"curiosita":"Giacomo Puccini was born on 22 December 1858 in Lucca. La Bohème, Tosca, Madama Butterfly and Turandot are his best-loved operas. He died in 1924, leaving Turandot unfinished."},
{"q":"The founding of the Red Cross","risposta":1863,"curiosita":"The Red Cross was founded in 1863 by Henry Dunant after he witnessed the Battle of Solferino in 1859. Today it's present in almost every country in the world."},
{"q":"The birth of Verdi","risposta":1813,"curiosita":"Giuseppe Verdi was born on 10 October 1813 in Le Roncole. Rigoletto, La Traviata, Otello and Aida are just some of his 28 operas. His name became an acronym for 'Vittorio Emanuele Re D'Italia'."},
{"q":"The birth of Beethoven","risposta":1770,"curiosita":"Beethoven was born in December 1770 in Bonn. He began losing his hearing in his late twenties and composed some of his greatest works when completely deaf."},
{"q":"The birth of Johann Sebastian Bach","risposta":1685,"curiosita":"Bach was born on 31 March 1685 and had 20 children. He died in 1750 largely forgotten, and was rediscovered thanks to Mendelssohn's historic 1829 performance of the St Matthew Passion."},
{"q":"The Battle of Waterloo","risposta":1815,"curiosita":"The Battle of Waterloo on 18 June 1815 marked Napoleon's final defeat, at the hands of the British and Prussians led by Wellington and Blücher."},
{"q":"The publication of Marx's Capital","risposta":1867,"curiosita":"The first volume of Capital was published on 14 September 1867. Marx only finished that one — the other two were completed by Engels after his death."},
{"q":"Watt's steam engine","risposta":1769,"curiosita":"James Watt patented his improved version of the steam engine in 1769. The unit of power, the watt, is named after him."},
{"q":"The birth of Florence Nightingale","risposta":1820,"curiosita":"Florence Nightingale was born on 12 May 1820 in Florence — hence her name. She transformed nursing care during the Crimean War and is the founder of modern nursing."},
{"q":"The US Declaration of Independence","risposta":1776,"curiosita":"The Declaration was adopted on 4 July 1776. Not everyone signed it that day — many signatures were added in August. John Hancock's huge signature became legendary."},
{"q":"The birth of Abraham Lincoln","risposta":1809,"curiosita":"Lincoln was born on 12 February 1809 in a log cabin in Kentucky. He was the 16th US president and led the abolition of slavery. He was assassinated on 14 April 1865 at Ford's Theatre."},
{"q":"The end of the American Civil War","risposta":1865,"curiosita":"The American Civil War ended in April 1865 with General Lee's surrender at Appomattox. It caused over 620,000 deaths."},
{"q":"The birth of Napoleon III","risposta":1808,"curiosita":"Napoleon III, nephew of Napoleon I, was born in 1808. He was the first president of the French Republic and then emperor. He transformed Paris through Baron Haussmann."},
{"q":"Röntgen's discovery of X-rays","risposta":1895,"curiosita":"Wilhelm Röntgen discovered X-rays on 8 November 1895. The first X-ray image was of his wife's hand; she said: 'I have seen my death'. Röntgen won the first Nobel Prize in Physics in 1901."},
{"q":"The birth of Copernicus","risposta":1473,"curiosita":"Nicolaus Copernicus was born on 19 February 1473 in Poland. His heliocentric model of the solar system was published in 1543, the year he died."},
{"q":"The birth of Archimedes","risposta":-287,"curiosita":"Archimedes was born around 287 BC in Syracuse. Legend says he discovered the principle of buoyancy in his bath and ran naked through the streets shouting 'Eureka!'."},
{"q":"The birth of Pythagoras","risposta":-570,"curiosita":"Pythagoras was born around 570 BC on the island of Samos. He founded an almost religious community in Croton, was a vegetarian and believed in reincarnation. The theorem bears his name but was already known to the Babylonians."},
{"q":"The founding of Plato's Academy","risposta":-387,"curiosita":"Plato founded the Academy in Athens around 387 BC. It's considered the first university in Western history, and survived in some form until AD 529."},
{"q":"The birth of Marco Polo","risposta":1254,"curiosita":"Marco Polo was born in 1254 in Venice. His journey to China lasted 24 years. The Travels were dictated in prison to Rustichello da Pisa. Many didn't believe him."},
{"q":"The birth of Cicero","risposta":-106,"curiosita":"Marcus Tullius Cicero was born in 106 BC in Arpinum. He was Rome's greatest orator, and about 900 of his letters survive — the largest private correspondence of antiquity."},
{"q":"The birth of Virgil","risposta":-70,"curiosita":"Virgil was born in 70 BC near Mantua. The Aeneid, his greatest work, was written for Augustus. He died before finishing it and asked for it to be destroyed."},
{"q":"The Great Fire of Rome","risposta":64,"curiosita":"The Great Fire of Rome in AD 64 burned for six days. Nero was accused of starting it — probably unfairly. He used the Christians as scapegoats."},
{"q":"The birth of Jules Verne","risposta":1828,"curiosita":"Jules Verne was born on 8 February 1828 in Nantes. He wrote Twenty Thousand Leagues Under the Sea, Around the World in 80 Days and Journey to the Centre of the Earth, imagining submarines and space travel long before they existed."},
{"q":"The birth of Victor Hugo","risposta":1802,"curiosita":"Hugo was born on 26 February 1802 in Besançon. Les Misérables and The Hunchback of Notre-Dame are his most famous works. When he died in 1885, 2 million people attended his funeral."},
{"q":"The birth of Alessandro Volta","risposta":1745,"curiosita":"Volta was born on 18 February 1745 in Como. He invented the electric battery in 1800 — the first source of continuous current. The volt is named after him."},
{"q":"The birth of Amerigo Vespucci","risposta":1454,"curiosita":"Vespucci was born on 9 March 1454 in Florence. He explored the coasts of South America and realised it was a new continent, not Asia. The cartographer Waldseemüller named it 'America' in his honour."},
{"q":"The birth of Raphael","risposta":1483,"curiosita":"Raphael was born on 6 April 1483 in Urbino. He died on his birthday, 6 April 1520, aged just 37. His most famous work is The School of Athens."},
{"q":"The birth of Caravaggio","risposta":1571,"curiosita":"Michelangelo Merisi da Caravaggio was born in 1571 in Milan. He revolutionised painting with dramatic chiaroscuro. He killed a man in a brawl in 1606 and lived as a fugitive until his death."},
{"q":"The birth of Titian","risposta":1488,"curiosita":"Titian was born around 1488 in Pieve di Cadore. He died in 1576 aged about 88 — exceptional for the time. He was Emperor Charles V's favourite painter."},
{"q":"The birth of Machiavelli","risposta":1469,"curiosita":"Niccolò Machiavelli was born on 3 May 1469 in Florence. He wrote The Prince in 1513 while in exile. 'Machiavellian' has entered every language to describe ruthless politics."},
{"q":"The founding of Constantinople","risposta":330,"curiosita":"Constantine I founded Constantinople on 11 May AD 330 on the ancient site of Byzantium. It was the capital of the Byzantine Empire for over 1,000 years, until 1453."},
{"q":"The Edict of Milan (religious freedom in the Roman Empire)","risposta":313,"curiosita":"In AD 313 Constantine I issued the Edict of Milan, granting religious freedom in the Roman Empire. It ended the persecution of Christians."},
{"q":"The birth of Rainer Maria Rilke","risposta":1875,"curiosita":"Rilke was born on 4 December 1875 in Prague. The Duino Elegies and Letters to a Young Poet are his best-loved works. He died of leukaemia in 1926 — legend links it to a rose thorn."},
{"q":"The Great Lisbon Earthquake","risposta":1755,"curiosita":"On 1 November 1755 an earthquake devastated Lisbon. The tsunami and fires killed tens of thousands of people. Voltaire wrote Candide partly in response to the catastrophe."},
{"q":"The birth of Erasmus of Rotterdam","risposta":1469,"curiosita":"Erasmus was born on 28 October around 1466-69 in Rotterdam. He was the leading intellectual of Northern European humanism. The university exchange programme named after him has let millions of students study abroad."},
{"q":"The birth of Thomas More","risposta":1478,"curiosita":"Thomas More was born on 7 February 1478 in London. He wrote Utopia in 1516. He was beheaded by Henry VIII in 1535 for refusing to recognise him as head of the Church of England."},
{"q":"The publication of Linnaeus's Systema Naturae","risposta":1735,"curiosita":"Carl Linnaeus published Systema Naturae in 1735, laying the groundwork for binomial nomenclature. Every living thing today has a scientific name based on his system."},
{"q":"The birth of Adam Smith","risposta":1723,"curiosita":"Adam Smith was born in June 1723 in Kirkcaldy, Scotland. The Wealth of Nations (1776) is a foundation of modern economics. The 'invisible hand' of the market is his idea."},
{"q":"The birth of Immanuel Kant","risposta":1724,"curiosita":"Kant was born on 22 April 1724 in Königsberg and hardly ever left his city. Legend says he was so punctual that people set their clocks by his daily walk."},
{"q":"The birth of René Descartes","risposta":1596,"curiosita":"Descartes was born on 31 March 1596 in France. 'Cogito, ergo sum' — I think, therefore I am — is his most famous phrase. He founded analytic geometry (the Cartesian plane is named after him)."},
{"q":"The birth of Voltaire","risposta":1694,"curiosita":"Voltaire was born on 21 November 1694 in Paris. He reportedly drank 40-50 cups of coffee a day and was imprisoned in the Bastille twice. His Candide is one of the most-read philosophical novels in history."},
{"q":"The birth of Jean-Jacques Rousseau","risposta":1712,"curiosita":"Rousseau was born on 28 June 1712 in Geneva. His ideas on the social contract deeply influenced the French Revolution and modern political philosophy."},
{"q":"The start of construction of the Parthenon","risposta":-447,"curiosita":"The Parthenon was built between 447 and 438 BC on the Acropolis of Athens, commissioned by Pericles. It stood largely intact for 2,000 years until an explosion badly damaged it in 1687."},
{"q":"The birth of Hippocrates","risposta":-460,"curiosita":"Hippocrates was born around 460 BC on the island of Kos. He's considered the father of medicine. The Hippocratic Oath is still the ethical foundation of the medical profession."},
{"q":"The Battle of Thermopylae","risposta":-480,"curiosita":"In 480 BC, 300 Spartans led by Leonidas held off Xerxes's Persian army for three days. They died almost to a man, but their stand helped Greece organise its counter-attack."},
{"q":"The founding of Carthage (estimate)","risposta":-814,"curiosita":"Carthage was founded around 814 BC by Phoenician colonists from Tyre. It became Rome's great rival in the Mediterranean. Hannibal set out from here to cross the Alps."},
{"q":"The birth of Hannibal","risposta":-247,"curiosita":"Hannibal Barca was born in 247 BC in Carthage. In 218 BC he crossed the Alps with 37 elephants and inflicted some of the worst defeats in Rome's history, but never took Rome."},
{"q":"The Visigoths' sack of Rome","risposta":410,"curiosita":"In AD 410 the Visigoths led by Alaric sacked Rome for three days — the first time in 800 years the city had fallen to a foreign enemy. Saint Augustine wrote The City of God in response."},
{"q":"Vespucci's exploration of South America","risposta":1499,"curiosita":"Amerigo Vespucci explored the coasts of South America in 1499-1500 and understood it was an unknown continent, not Asia. That's why the continent bears his name."},
{"q":"The birth of Francisco de Goya","risposta":1746,"curiosita":"Goya was born on 30 March 1746 in Fuendetodos, Spain. Court painter to Charles IV, he went deaf in 1792 and his work grew ever darker. His 'Black Paintings' are among the most unsettling in Western art."},
{"q":"The birth of Giacomo Leopardi","risposta":1798,"curiosita":"Leopardi was born on 29 June 1798 in Recanati. His 'cosmic pessimism' made him the greatest Italian poet of Romanticism. L'Infinito is his most famous poem."},
{"q":"The founding of UNESCO","risposta":1945,"curiosita":"UNESCO was founded on 16 November 1945 in London. Its mission is to promote peace and security through education, science and culture. It has 194 member states."},
{"q":"The publication of Kant's Critique of Pure Reason","risposta":1781,"curiosita":"Kant published the Critique of Pure Reason in 1781, after 11 years of reflection. It's considered one of the most important works of Western philosophy."},
{"q":"The founding of FIFA","risposta":1904,"curiosita":"FIFA was founded on 21 May 1904 in Paris by 7 European countries. Today it has 211 member associations — more than the member states of the UN."},
{"q":"The first Football World Cup","risposta":1930,"curiosita":"The first World Cup was held in Uruguay in 1930, and Uruguay won at home. Only 13 teams took part — most European sides declined because of the long sea voyage."},
{"q":"The birth of Pelé","risposta":1940,"curiosita":"Pelé was born on 23 October 1940 in Três Corações, Brazil. He scored over 1,200 goals in his career and won three World Cups (1958, 1962, 1970) — the only player ever to do so."},
{"q":"The birth of Muhammad Ali","risposta":1942,"curiosita":"Muhammad Ali was born on 17 January 1942 in Louisville, Kentucky. He became world heavyweight champion at 22. He refused to fight in Vietnam and was stripped of his title for over three years."},
{"q":"The birth of Ayrton Senna","risposta":1960,"curiosita":"Senna was born on 21 March 1960 in São Paulo and won 3 F1 world titles. He died on 1 May 1994 at the San Marino Grand Prix at Imola; since then F1 safety has improved enormously."},
{"q":"The first Formula 1 World Championship","risposta":1950,"curiosita":"The first F1 World Championship was held in 1950. Nino Farina with Alfa Romeo was the first champion, and the British Grand Prix at Silverstone was the first race."},
{"q":"The birth of Roger Federer","risposta":1981,"curiosita":"Federer was born on 8 August 1981 in Basel. He won 20 Grand Slam titles and is considered by many the greatest tennis player of all time."},
{"q":"The first modern Olympic Games","risposta":1896,"curiosita":"The first modern Olympics were held in Athens in 1896, with 241 athletes from 14 countries. Women couldn't compete — they took part for the first time in Paris in 1900."},
{"q":"The founding of Scuderia Ferrari","risposta":1929,"curiosita":"Enzo Ferrari founded Scuderia Ferrari in Modena in 1929 as a racing team for Alfa Romeo cars. The first car bearing the Ferrari name came out in 1947."},
{"q":"The birth of Enzo Ferrari","risposta":1898,"curiosita":"Enzo Ferrari was born on 18 February 1898 in Modena. He built a motoring empire out of his passion for racing, and died in 1988 aged 90."},
{"q":"The birth of Michael Jackson","risposta":1958,"curiosita":"Michael Jackson was born on 29 August 1958 in Gary, Indiana. Thriller (1982) is the best-selling album in history. He first performed the moonwalk on TV on 25 March 1983."},
{"q":"The birth of Madonna","risposta":1958,"curiosita":"Madonna was born on 16 August 1958 in Bay City, Michigan. She's the best-selling female solo artist in history, with over 300 million records sold."},
{"q":"The birth of David Bowie","risposta":1947,"curiosita":"Bowie was born on 8 January 1947 in London and sold over 100 million records. His eyes looked two different colours because of anisocoria: one pupil stayed dilated after a teenage punch."},
{"q":"The birth of Freddie Mercury","risposta":1946,"curiosita":"Freddie Mercury was born on 5 September 1946 in Zanzibar. His real name was Farrokh Bulsara. Bohemian Rhapsody remains one of the most-played songs of all time."},
{"q":"The birth of Elvis Presley","risposta":1935,"curiosita":"Elvis was born on 8 January 1935 in Tupelo, Mississippi. He sold over 500 million records and is still one of the highest-earning artists — decades after his death in 1977."},
{"q":"The birth of John Lennon","risposta":1940,"curiosita":"Lennon was born on 9 October 1940 in Liverpool. He founded the Beatles in 1960. He was shot dead on 8 December 1980 outside the Dakota building in New York."},
{"q":"The first public radio broadcast","risposta":1920,"curiosita":"The first regular commercial radio broadcast took place on 2 November 1920 from KDKA in Pittsburgh, reporting the US presidential election results."},
{"q":"Berners-Lee's invention of the World Wide Web","risposta":1989,"curiosita":"Tim Berners-Lee proposed the World Wide Web in 1989 while working at CERN in Geneva. The first website went online on 6 August 1991. He never patented it — he gave it to the world."},
{"q":"The birth of Stephen Hawking","risposta":1942,"curiosita":"Hawking was born on 8 January 1942 in Oxford — exactly 300 years after Galileo's death. Diagnosed with ALS at 21 and given 2 years to live, he lived another 55."},
{"q":"The publication of George Orwell's 1984","risposta":1949,"curiosita":"George Orwell published 1984 on 8 June 1949, a few months before he died. It introduced Big Brother, doublethink and Newspeak, and is one of the best-selling novels of all time."},
{"q":"The birth of Woody Allen","risposta":1935,"curiosita":"Woody Allen was born on 1 December 1935 in Brooklyn. He directed about one film a year for almost 50 years and won 4 Oscars."},
{"q":"The founding of Netflix","risposta":1997,"curiosita":"Reed Hastings and Marc Randolph founded Netflix on 29 August 1997 as a mail-order DVD rental service. It moved into streaming in 2007."}];
var ANNO_GIUSTO_DATA_ES=[{"q":"La caída del Muro de Berlín","risposta":1989,"curiosita":"El 9 de noviembre de 1989 miles de berlineses empezaron a derribar el muro que dividía la ciudad desde 1961. Fue el final simbólico de la Guerra Fría."},
{"q":"La primera llegada del hombre a la Luna","risposta":1969,"curiosita":"El 20 de julio de 1969 Neil Armstrong y Buzz Aldrin alunizaron con el Apolo 11. Armstrong dijo: 'Es un pequeño paso para el hombre, un gran salto para la humanidad'."},
{"q":"El nacimiento de internet (ARPANET)","risposta":1969,"curiosita":"El 29 de octubre de 1969 se envió el primer mensaje por ARPANET: 'lo'. El sistema se colgó tras dos letras, pero la red había nacido."},
{"q":"La invención de la imprenta de tipos móviles de Gutenberg","risposta":1450,"curiosita":"Hacia 1450 Gutenberg inventó la imprenta de tipos móviles. La Biblia de Gutenberg fue el primer gran libro impreso en Europa: unas 180 copias."},
{"q":"La llegada de Colón a América","risposta":1492,"curiosita":"El 12 de octubre de 1492 Colón avistó tierra en el Caribe. Creía haber llegado a Asia y murió sin saber que había encontrado un nuevo continente."},
{"q":"El inicio de la Primera Revolución Industrial","risposta":1760,"curiosita":"La Revolución Industrial empezó en Inglaterra hacia 1760, con innovaciones como la máquina de vapor perfeccionada por James Watt. Cambió para siempre el trabajo humano."},
{"q":"El inicio de la Revolución Francesa","risposta":1789,"curiosita":"El 14 de julio de 1789 cayó la Bastilla. La Revolución Francesa dio al mundo los ideales de libertad, igualdad y fraternidad."},
{"q":"El nacimiento de Leonardo da Vinci","risposta":1452,"curiosita":"Leonardo nació el 15 de abril de 1452 en Anchiano, cerca de Vinci. Pintor, científico, ingeniero: el genio más completo del Renacimiento."},
{"q":"La muerte de Napoleón Bonaparte","risposta":1821,"curiosita":"Napoleón murió el 5 de mayo de 1821 desterrado en la isla de Santa Elena, a los 51 años. Aún se discute si fue envenenado con arsénico."},
{"q":"La fundación de Roma (según la tradición)","risposta":-753,"curiosita":"Según la tradición, Rómulo fundó Roma en el 753 a. C. En realidad, los primeros asentamientos de la zona se remontan a hacia el 1000 a. C."},
{"q":"El inicio de la Primera Guerra Mundial","risposta":1914,"curiosita":"El 28 de junio de 1914 fue asesinado en Sarajevo el archiduque Francisco Fernando. Cuatro años después la guerra había causado más de 20 millones de muertos."},
{"q":"El fin de la Segunda Guerra Mundial","risposta":1945,"curiosita":"El 2 de septiembre de 1945 Japón firmó la rendición tras las bombas atómicas de Hiroshima y Nagasaki. Entre 70 y 85 millones de personas murieron en el conflicto."},
{"q":"El lanzamiento del primer iPhone","risposta":2007,"curiosita":"Steve Jobs presentó el primer iPhone el 9 de enero de 2007 como 'un iPod, un teléfono y un comunicador de internet'. Nadie entendió enseguida cuánto lo cambiaría todo."},
{"q":"El nacimiento de Facebook","risposta":2004,"curiosita":"Mark Zuckerberg lanzó Facebook el 4 de febrero de 2004 desde Harvard. Al principio se llamaba 'TheFacebook' y era solo para universitarios."},
{"q":"El nacimiento de YouTube","risposta":2005,"curiosita":"YouTube se fundó el 14 de febrero de 2005 por tres exempleados de PayPal. El primer vídeo se llamaba 'Me at the zoo' y sigue en línea."},
{"q":"La fundación de Google","risposta":1998,"curiosita":"Larry Page y Sergey Brin fundaron Google el 4 de septiembre de 1998 en un garaje de Menlo Park. El nombre viene de 'gúgol', 10 elevado a 100."},
{"q":"El primer tuit de Twitter","risposta":2006,"curiosita":"Jack Dorsey publicó el primer tuit el 21 de marzo de 2006: 'just setting up my twttr'. La plataforma se abrió al público en julio de ese año."},
{"q":"La caída del Imperio romano de Occidente","risposta":476,"curiosita":"En el 476 d. C. Odoacro depuso al último emperador romano de Occidente, Rómulo Augústulo. Convencionalmente marca el fin de la Antigüedad y el inicio de la Edad Media."},
{"q":"El nacimiento de William Shakespeare","risposta":1564,"curiosita":"Shakespeare nació en abril de 1564 en Stratford-upon-Avon. Escribió unas 37 obras de teatro y 154 sonetos, y sigue siendo el dramaturgo más representado del mundo."},
{"q":"La publicación de la teoría de la relatividad de Einstein","risposta":1905,"curiosita":"En 1905 Einstein publicó cuatro artículos revolucionarios, entre ellos la relatividad especial y E=mc². Se conoce como su 'año milagroso'."},
{"q":"El inicio de la construcción de la Gran Muralla china","risposta":-221,"curiosita":"La Gran Muralla empezó a unificarse en el 221 a. C. bajo el emperador Qin Shi Huang. Contra lo que dice la leyenda, no se ve a simple vista desde el espacio."},
{"q":"El nacimiento de Isaac Newton","risposta":1643,"curiosita":"Newton nació el 4 de enero de 1643 en Inglaterra. Según la leyenda, la caída de una manzana lo llevó a la teoría de la gravitación universal."},
{"q":"La muerte de Julio César","risposta":-44,"curiosita":"Julio César fue asesinado en los idus de marzo (15 de marzo) del 44 a. C. Recibió 23 puñaladas de senadores encabezados por Bruto y Casio."},
{"q":"La inauguración del Coliseo","risposta":80,"curiosita":"El Coliseo fue inaugurado en el 80 d. C. por el emperador Tito con 100 días de juegos. Podía albergar hasta 80.000 espectadores."},
{"q":"La Revolución rusa de Octubre","risposta":1917,"curiosita":"La Revolución de Octubre de 1917 llevó al poder a los bolcheviques de Lenin. Nació el primer Estado comunista de la historia, que duró hasta 1991."},
{"q":"La invención del teléfono por Bell","risposta":1876,"curiosita":"Alexander Graham Bell patentó el teléfono el 7 de marzo de 1876. La primera frase transmitida fue: 'Señor Watson, venga aquí, quiero verle'."},
{"q":"El nacimiento de Mozart","risposta":1756,"curiosita":"Wolfgang Amadeus Mozart nació el 27 de enero de 1756 en Salzburgo. Compuso su primera sinfonía a los 8 años y murió a los 35, dejando más de 600 obras."},
{"q":"El nacimiento de Miguel Ángel","risposta":1475,"curiosita":"Miguel Ángel nació el 6 de marzo de 1475. Pintó la bóveda de la Capilla Sixtina entre 1508 y 1512, trabajando cuatro años sobre altos andamios."},
{"q":"La conclusión de la Divina Comedia de Dante","risposta":1321,"curiosita":"Dante terminó la Divina Comedia poco antes de morir en 1321. Se considera la mayor obra de la literatura italiana y una de las más importantes del mundo."},
{"q":"El fin del apartheid en Sudáfrica","risposta":1994,"curiosita":"En 1994 Sudáfrica celebró sus primeras elecciones democráticas. Nelson Mandela, tras 27 años de cárcel, se convirtió en el primer presidente negro del país."},
{"q":"El lanzamiento del Sputnik (el primer satélite artificial)","risposta":1957,"curiosita":"El 4 de octubre de 1957 la URSS lanzó el Sputnik, el primer satélite artificial de la historia. Era del tamaño de un balón de playa y solo emitía un pitido de radio."},
{"q":"La fundación de las Naciones Unidas","risposta":1945,"curiosita":"Las Naciones Unidas se fundaron el 24 de octubre de 1945 con 51 países, tras la Segunda Guerra Mundial. Hoy cuentan con 193 Estados miembros."},
{"q":"La Carta Magna","risposta":1215,"curiosita":"La Carta Magna fue sellada el 15 de junio de 1215 por el rey Juan de Inglaterra. Se considera una de las bases del derecho constitucional moderno."},
{"q":"El nacimiento de Albert Einstein","risposta":1879,"curiosita":"Einstein nació el 14 de marzo de 1879 en Ulm, Alemania. No era un alumno brillante, pero el mito de que suspendía matemáticas es falso."},
{"q":"El nacimiento de Galileo Galilei","risposta":1564,"curiosita":"Galileo nació el 15 de febrero de 1564 en Pisa. Perfeccionó el telescopio, lo apuntó al cielo y defendió que la Tierra gira alrededor del Sol, por lo que fue juzgado por la Inquisición."},
{"q":"La fundación de la Unión Europea (Tratado de Maastricht)","risposta":1993,"curiosita":"El Tratado de Maastricht entró en vigor el 1 de noviembre de 1993 y creó formalmente la Unión Europea. Abrió el camino al euro y a la libre circulación."},
{"q":"El lanzamiento de Amazon","risposta":1994,"curiosita":"Jeff Bezos fundó Amazon el 5 de julio de 1994 en un garaje de Seattle. Al principio solo vendía libros. Hoy es uno de los mayores mercados en línea del mundo."},
{"q":"El nacimiento de Cleopatra","risposta":-69,"curiosita":"Cleopatra nació en el 69 a. C. Era de origen griego macedonio, no egipcio. Fue la última reina ptolemaica y, según se cuenta, hablaba 9 idiomas."},
{"q":"La construcción de la Gran Pirámide de Guiza","risposta":-2560,"curiosita":"La Gran Pirámide de Guiza se construyó hacia el 2560 a. C. para el faraón Keops. Durante más de 3.800 años fue la estructura más alta del mundo."},
{"q":"El nacimiento de Jesús (estimación histórica)","risposta":-4,"curiosita":"Irónicamente, Jesús nació probablemente entre el 6 y el 4 a. C. El error del calendario lo cometió el monje Dionisio el Exiguo en el siglo VI."},
{"q":"La fundación de Venecia","risposta":421,"curiosita":"Según la tradición, Venecia se fundó el 25 de marzo del 421 d. C. Se construyó sobre 118 islas unidas por más de 400 puentes y durante siglos fue la potencia comercial del Mediterráneo."},
{"q":"El nacimiento de Napoleón Bonaparte","risposta":1769,"curiosita":"Napoleón nació el 15 de agosto de 1769 en Ajaccio, Córcega, justo después de que Francia se hiciera con la isla. Y no era bajo: medía 1,69 m, la media de la época."},
{"q":"La publicación de El origen de las especies de Darwin","risposta":1859,"curiosita":"Darwin publicó El origen de las especies el 24 de noviembre de 1859. Los 1.250 ejemplares de la primera edición se agotaron el primer día."},
{"q":"El nacimiento de Karl Marx","risposta":1818,"curiosita":"Karl Marx nació el 5 de mayo de 1818 en Tréveris. El Manifiesto comunista, escrito con Engels, se publicó en 1848."},
{"q":"La llegada de la peste negra a Europa","risposta":1347,"curiosita":"La peste negra llegó a Europa en 1347 y en cinco años mató a entre el 30% y el 60% de la población europea: unos 25 millones de personas."},
{"q":"El nacimiento de Mahoma","risposta":570,"curiosita":"Mahoma nació hacia el 570 d. C. en La Meca. Recibió sus primeras revelaciones en el 610. El islam es hoy una de las religiones que más crece en el mundo."},
{"q":"El descubrimiento de la penicilina","risposta":1928,"curiosita":"Alexander Fleming descubrió la penicilina por casualidad el 3 de septiembre de 1928, al ver que un moho había matado las bacterias de una placa de Petri. Salvó millones de vidas."},
{"q":"El fin de la Segunda Guerra Mundial en Europa (Día de la Victoria)","risposta":1945,"curiosita":"El 8 de mayo de 1945 entró en vigor la rendición incondicional de Alemania. Hubo celebraciones espontáneas en toda Europa. La guerra en el Pacífico acabaría en agosto."},
{"q":"El nacimiento de Steve Jobs","risposta":1955,"curiosita":"Steve Jobs nació el 24 de febrero de 1955 y fue adoptado al nacer. Fundó Apple en 1976 con Steve Wozniak en un garaje y revolucionó los ordenadores, la música, la telefonía y la animación."},
{"q":"El asesinato de John F. Kennedy","risposta":1963,"curiosita":"JFK fue asesinado el 22 de noviembre de 1963 en Dallas durante un desfile. Lee Harvey Oswald fue detenido, pero Jack Ruby lo mató dos días después."},
{"q":"El inicio de la Primera Cruzada","risposta":1096,"curiosita":"El papa Urbano II convocó la Primera Cruzada en 1095. Los cruzados partieron en 1096 y tomaron Jerusalén en 1099 tras un sangriento asedio."},
{"q":"El nacimiento de Charles Darwin","risposta":1809,"curiosita":"Darwin nació el 12 de febrero de 1809, el mismo día que Abraham Lincoln. Estudió medicina y luego teología antes de convertirse en el naturalista más revolucionario de la historia."},
{"q":"El hundimiento del Titanic","risposta":1912,"curiosita":"El Titanic se hundió el 15 de abril de 1912 en su viaje inaugural. Murieron unas 1.500 personas. El pecio no se encontró en el fondo del Atlántico hasta 1985."},
{"q":"El nacimiento de Adolf Hitler","risposta":1889,"curiosita":"Hitler nació el 20 de abril de 1889 en Austria. La Academia de Bellas Artes de Viena lo rechazó dos veces, una humillación que lo marcó profundamente."},
{"q":"El fin de la Unión Soviética","risposta":1991,"curiosita":"El 25 de diciembre de 1991 Gorbachov dimitió y la URSS dejó de existir oficialmente, dividida en 15 Estados independientes. La Guerra Fría había terminado."},
{"q":"La primera ascensión al Everest","risposta":1953,"curiosita":"El 29 de mayo de 1953 Edmund Hillary y Tenzing Norgay fueron los primeros en llegar a la cima del Everest (8.849 m). La noticia llegó a Londres el día de la coronación de Isabel II."},
{"q":"La bombilla de Edison","risposta":1879,"curiosita":"Edison patentó su bombilla en 1879-80. Muchos habían trabajado antes en ella; su mérito fue hacerla práctica y rentable."},
{"q":"La fundación de Apple","risposta":1976,"curiosita":"Apple se fundó el 1 de abril de 1976 por Steve Jobs, Steve Wozniak y Ronald Wayne. Wayne vendió su parte por 800 dólares: hoy valdría miles de millones."},
{"q":"El nacimiento de Winston Churchill","risposta":1874,"curiosita":"Churchill nació el 30 de noviembre de 1874. Ganó el Nobel de Literatura en 1953, no el de la Paz. Era un pintor apasionado y escribió más de 40 libros."},
{"q":"La invención del cine (los hermanos Lumière)","risposta":1895,"curiosita":"El 28 de diciembre de 1895 los hermanos Lumière hicieron la primera proyección pública de cine en París. Según la leyenda, algunos espectadores huyeron al ver llegar un tren en la pantalla."},
{"q":"El nacimiento de Frida Kahlo","risposta":1907,"curiosita":"Frida Kahlo nació el 6 de julio de 1907 en Coyoacán, México. Tras un grave accidente a los 18 años empezó a pintar. Su vida fue una mezcla inseparable de arte y dolor."},
{"q":"El primer servicio regular de televisión pública (BBC)","risposta":1936,"curiosita":"La BBC inició el primer servicio regular de televisión pública el 2 de noviembre de 1936, con 2 horas al día. La televisión se suspendió durante la Segunda Guerra Mundial."},
{"q":"La aprobación de la Constitución italiana","risposta":1947,"curiosita":"La Constitución italiana se aprobó el 22 de diciembre de 1947 y entró en vigor el 1 de enero de 1948. La redactó la Asamblea Constituyente tras la caída del fascismo."},
{"q":"El nacimiento de Sigmund Freud","risposta":1856,"curiosita":"Freud nació el 6 de mayo de 1856 en Freiberg. Fundó el psicoanálisis. Fumaba 20 puros al día y siguió haciéndolo incluso tras 33 operaciones por un cáncer de mandíbula."},
{"q":"La primera llamada con un prototipo de teléfono móvil","risposta":1973,"curiosita":"Martin Cooper, de Motorola, hizo la primera llamada con un prototipo de móvil el 3 de abril de 1973. El teléfono pesaba cerca de 1 kg y tenía 30 minutos de autonomía."},
{"q":"El nacimiento de Nikola Tesla","risposta":1856,"curiosita":"Tesla nació el 10 de julio de 1856 en la actual Croacia, en una familia serbia. Desarrolló el sistema de corriente alterna. Murió pobre y solo en un hotel en 1943; muchas de sus patentes habían acabado en manos de Westinghouse."},
{"q":"El nacimiento de Marie Curie","risposta":1867,"curiosita":"Marie Curie nació el 7 de noviembre de 1867 en Varsovia. Fue la primera mujer en ganar un Nobel y la única persona premiada en dos ciencias distintas (Física 1903, Química 1911)."},
{"q":"La caída de Constantinopla","risposta":1453,"curiosita":"El 29 de mayo de 1453 los turcos otomanos de Mehmed II tomaron Constantinopla y pusieron fin al Imperio bizantino. Convencionalmente marca el fin de la Edad Media."},
{"q":"El inicio del Concilio de Trento","risposta":1545,"curiosita":"El Concilio de Trento empezó en 1545 y duró casi 20 años. Fue la respuesta de la Iglesia católica a la Reforma protestante de Lutero."},
{"q":"El nacimiento de Martin Luther King Jr.","risposta":1929,"curiosita":"MLK nació el 15 de enero de 1929 en Atlanta. Pronunció su discurso 'I Have a Dream' el 28 de agosto de 1963 ante 250.000 personas en Washington."},
{"q":"El bombardeo atómico de Hiroshima","risposta":1945,"curiosita":"El 6 de agosto de 1945 se lanzó la bomba atómica 'Little Boy' sobre Hiroshima. Unas 80.000 personas murieron en segundos; a final de año las víctimas llegaban a 140.000."},
{"q":"La fundación de Microsoft","risposta":1975,"curiosita":"Bill Gates y Paul Allen fundaron Microsoft el 4 de abril de 1975 en Albuquerque, Nuevo México. El nombre une 'microcomputer' y 'software'."},
{"q":"El nacimiento de Walt Disney","risposta":1901,"curiosita":"Walt Disney nació el 5 de diciembre de 1901 en Chicago. Creó a Mickey Mouse en 1928. Blancanieves (1937) fue el primer largometraje animado de Disney y un éxito mundial."},
{"q":"El vuelo de los hermanos Wright (el primer avión a motor)","risposta":1903,"curiosita":"El 17 de diciembre de 1903 Orville Wright voló 12 segundos en Kitty Hawk. Pocos periódicos dieron la noticia: para muchos era demasiado increíble."},
{"q":"El nacimiento de Nelson Mandela","risposta":1918,"curiosita":"Nelson Mandela nació el 18 de julio de 1918. Pasó 27 años en prisión y llegó a presidente de Sudáfrica en 1994, a los 75 años."},
{"q":"El nacimiento de Pablo Picasso","risposta":1881,"curiosita":"Picasso nació el 25 de octubre de 1881 en Málaga. Su nombre completo tenía más de 20 partes. Fundó el cubismo con Georges Braque hacia 1907."},
{"q":"El descubrimiento de la estructura del ADN (Watson y Crick)","risposta":1953,"curiosita":"Watson y Crick publicaron la estructura del ADN el 25 de abril de 1953. Su trabajo se basó en la Foto 51 de Rosalind Franklin, que nunca recibió el Nobel."},
{"q":"El nacimiento de Confucio","risposta":-551,"curiosita":"Confucio nació en el 551 a. C. en China. Su filosofía sobre la ética, el gobierno y las relaciones sociales sigue influyendo en la cultura de Asia oriental."},
{"q":"El nacimiento de Alejandro Magno","risposta":-356,"curiosita":"Alejandro nació en el 356 a. C. en Pela, Macedonia. En solo 13 años conquistó un enorme imperio. Murió a los 32 años, quizá de fiebre tifoidea."},
{"q":"El nacimiento de Cristóbal Colón","risposta":1451,"curiosita":"Colón nació en 1451 en Génova. Murió en 1506 convencido de haber llegado a Asia. El continente al que llegó recibió el nombre de otro explorador, Américo Vespucio."},
{"q":"El inicio de la Reforma protestante de Lutero","risposta":1517,"curiosita":"El 31 de octubre de 1517 Martín Lutero publicó sus 95 tesis en Wittenberg. Así empezó la Reforma que dividió la cristiandad occidental."},
{"q":"El nacimiento de Aristóteles","risposta":-384,"curiosita":"Aristóteles nació en el 384 a. C. en Estagira. Discípulo de Platón y maestro de Alejandro Magno, fundó la lógica formal y escribió sobre física, biología, política y poética."},
{"q":"El nacimiento de Platón","risposta":-428,"curiosita":"Platón nació hacia el 428 a. C. en Atenas. Discípulo de Sócrates, fundó la Academia de Atenas, la primera institución de enseñanza superior del mundo occidental."},
{"q":"El nacimiento de Sócrates","risposta":-470,"curiosita":"Sócrates nació hacia el 470 a. C. en Atenas. No escribió nada: todo lo que sabemos procede de Platón y Jenofonte. Fue condenado a muerte en el 399 a. C. bebiendo cicuta."},
{"q":"La vida de Homero (estimación)","risposta":-800,"curiosita":"Homero vivió probablemente hacia el 800 a. C. Se le atribuyen la Ilíada y la Odisea, aunque algunos estudiosos creen que fueron obra de varios autores."},
{"q":"El nacimiento de Dante Alighieri","risposta":1265,"curiosita":"Dante nació en mayo de 1265 en Florencia. Fue desterrado de su ciudad en 1302 y nunca volvió. Escribió la Divina Comedia en el exilio."},
{"q":"La publicación del Quijote de Cervantes","risposta":1605,"curiosita":"El Quijote se publicó en 1605. Se considera la primera novela moderna y es uno de los libros más traducidos del mundo."},
{"q":"El nacimiento de Benito Mussolini","risposta":1883,"curiosita":"Mussolini nació el 29 de julio de 1883 en Predappio. De joven fue socialista y periodista. Fundó el fascismo en 1919 y se convirtió en dictador de Italia en 1925."},
{"q":"El nacimiento de Mahatma Gandhi","risposta":1869,"curiosita":"Gandhi nació el 2 de octubre de 1869 en la India. Su filosofía de la no violencia (ahimsa) inspiró movimientos por los derechos civiles en todo el mundo, entre ellos el de Martin Luther King."},
{"q":"El inicio de la Gran Depresión","risposta":1929,"curiosita":"El crac de Wall Street del 29 de octubre de 1929 desencadenó la Gran Depresión. En 1933 uno de cada cuatro estadounidenses estaba en paro."},
{"q":"El nacimiento de Thomas Edison","risposta":1847,"curiosita":"Edison nació el 11 de febrero de 1847. Registró 1.093 patentes, todo un récord. Su rivalidad con Tesla por la corriente eléctrica fue épica y despiadada."},
{"q":"El nacimiento de Charles Chaplin","risposta":1889,"curiosita":"Chaplin nació el 16 de abril de 1889 en Londres en la pobreza más absoluta. Creó a Charlot, el vagabundo de bombín y bastón que lo convirtió en la estrella del cine mudo."},
{"q":"La fundación del Imperio romano","risposta":-27,"curiosita":"Octavio se convirtió en el primer emperador romano con el título de Augusto en el 27 a. C. El Imperio duró en Occidente hasta el 476 d. C.: más de 500 años."},
{"q":"El fin de las Cruzadas","risposta":1291,"curiosita":"La caída de Acre en 1291 marcó el fin de las Cruzadas en Tierra Santa. Los cristianos perdieron definitivamente los territorios conquistados en 1099."},
{"q":"El nacimiento de Friedrich Nietzsche","risposta":1844,"curiosita":"Nietzsche nació el 15 de octubre de 1844. Escribió la primera parte de Así habló Zaratustra en unos diez días. Según el relato tradicional, se derrumbó en Turín en 1889 abrazado a un caballo."},
{"q":"La publicación del primer libro de Harry Potter","risposta":1997,"curiosita":"Harry Potter y la piedra filosofal se publicó el 26 de junio de 1997 con Bloomsbury. J. K. Rowling era una madre soltera que escribía en cafeterías de Edimburgo."},
{"q":"La invención de la radio por Marconi","risposta":1895,"curiosita":"Guglielmo Marconi empezó sus experimentos de radio en 1895. En 1901 envió la primera señal a través del Atlántico. Ganó el Nobel de Física en 1909."},
{"q":"El nacimiento de Vincent van Gogh","risposta":1853,"curiosita":"Van Gogh nació el 30 de marzo de 1853 en los Países Bajos. Vendió muy pocos cuadros en vida y se cortó parte de la oreja en 1888. Hoy sus obras valen decenas de millones."},
{"q":"El nacimiento de Puccini","risposta":1858,"curiosita":"Giacomo Puccini nació el 22 de diciembre de 1858 en Lucca. La Bohème, Tosca, Madama Butterfly y Turandot son sus óperas más célebres. Murió en 1924 dejando Turandot inacabada."},
{"q":"La fundación de la Cruz Roja","risposta":1863,"curiosita":"La Cruz Roja se fundó en 1863 por iniciativa de Henry Dunant, tras presenciar la batalla de Solferino en 1859. Hoy está presente en casi todos los países del mundo."},
{"q":"El nacimiento de Verdi","risposta":1813,"curiosita":"Giuseppe Verdi nació el 10 de octubre de 1813 en Le Roncole. Rigoletto, La Traviata, Otello y Aida son solo algunas de sus 28 óperas. Su nombre se convirtió en el acrónimo de 'Vittorio Emanuele Re D'Italia'."},
{"q":"El nacimiento de Beethoven","risposta":1770,"curiosita":"Beethoven nació en diciembre de 1770 en Bonn. Empezó a perder el oído pasados los 25 años y compuso algunas de sus mayores obras completamente sordo."},
{"q":"El nacimiento de Johann Sebastian Bach","risposta":1685,"curiosita":"Bach nació el 31 de marzo de 1685 y tuvo 20 hijos. Murió en 1750 casi olvidado y fue redescubierto gracias a la histórica interpretación de la Pasión según san Mateo de Mendelssohn en 1829."},
{"q":"La batalla de Waterloo","risposta":1815,"curiosita":"La batalla de Waterloo, el 18 de junio de 1815, supuso la derrota definitiva de Napoleón frente a británicos y prusianos, dirigidos por Wellington y Blücher."},
{"q":"La publicación de El capital de Marx","risposta":1867,"curiosita":"El primer tomo de El capital se publicó el 14 de septiembre de 1867. Marx solo terminó ese; los otros dos los completó Engels tras su muerte."},
{"q":"La máquina de vapor de Watt","risposta":1769,"curiosita":"James Watt patentó su versión mejorada de la máquina de vapor en 1769. La unidad de potencia, el vatio, lleva su nombre."},
{"q":"El nacimiento de Florence Nightingale","risposta":1820,"curiosita":"Florence Nightingale nació el 12 de mayo de 1820 en Florencia, de ahí su nombre. Transformó la atención sanitaria en la guerra de Crimea y es la fundadora de la enfermería moderna."},
{"q":"La Declaración de Independencia de EE. UU.","risposta":1776,"curiosita":"La Declaración se aprobó el 4 de julio de 1776. No todos la firmaron ese día: muchas firmas se añadieron en agosto. La enorme firma de John Hancock se hizo legendaria."},
{"q":"El nacimiento de Abraham Lincoln","risposta":1809,"curiosita":"Lincoln nació el 12 de febrero de 1809 en una cabaña de troncos en Kentucky. Fue el 16.º presidente de EE. UU. e impulsó la abolición de la esclavitud. Fue asesinado el 14 de abril de 1865 en el teatro Ford."},
{"q":"El fin de la guerra de Secesión estadounidense","risposta":1865,"curiosita":"La guerra civil estadounidense terminó en abril de 1865 con la rendición del general Lee en Appomattox. Causó más de 620.000 muertos."},
{"q":"El nacimiento de Napoleón III","risposta":1808,"curiosita":"Napoleón III, sobrino de Napoleón I, nació en 1808. Fue el primer presidente de la República francesa y luego emperador. Transformó París con el barón Haussmann."},
{"q":"El descubrimiento de los rayos X por Röntgen","risposta":1895,"curiosita":"Wilhelm Röntgen descubrió los rayos X el 8 de noviembre de 1895. La primera radiografía fue de la mano de su esposa, que dijo: 'He visto mi muerte'. Röntgen ganó el primer Nobel de Física en 1901."},
{"q":"El nacimiento de Copérnico","risposta":1473,"curiosita":"Nicolás Copérnico nació el 19 de febrero de 1473 en Polonia. Su modelo heliocéntrico del sistema solar se publicó en 1543, el año de su muerte."},
{"q":"El nacimiento de Arquímedes","risposta":-287,"curiosita":"Arquímedes nació hacia el 287 a. C. en Siracusa. Según la leyenda, descubrió el principio de flotación en el baño y corrió desnudo por las calles gritando '¡Eureka!'."},
{"q":"El nacimiento de Pitágoras","risposta":-570,"curiosita":"Pitágoras nació hacia el 570 a. C. en la isla de Samos. Fundó una comunidad casi religiosa en Crotona, era vegetariano y creía en la reencarnación. El teorema lleva su nombre, pero ya lo conocían los babilonios."},
{"q":"La fundación de la Academia de Platón","risposta":-387,"curiosita":"Platón fundó la Academia de Atenas hacia el 387 a. C. Se considera la primera universidad de la historia occidental y sobrevivió de alguna forma hasta el 529 d. C."},
{"q":"El nacimiento de Marco Polo","risposta":1254,"curiosita":"Marco Polo nació en 1254 en Venecia. Su viaje a China duró 24 años. El libro de sus viajes lo dictó en la cárcel a Rustichello de Pisa. Muchos no le creyeron."},
{"q":"El nacimiento de Cicerón","risposta":-106,"curiosita":"Marco Tulio Cicerón nació en el 106 a. C. en Arpino. Fue el mayor orador romano y se conservan unas 900 cartas suyas: la mayor correspondencia privada de la Antigüedad."},
{"q":"El nacimiento de Virgilio","risposta":-70,"curiosita":"Virgilio nació en el 70 a. C. cerca de Mantua. La Eneida, su gran obra, la escribió para Augusto. Murió antes de terminarla y pidió que la destruyeran."},
{"q":"El gran incendio de Roma","risposta":64,"curiosita":"El gran incendio de Roma del 64 d. C. duró seis días. Se acusó a Nerón de provocarlo, probablemente sin razón. Él culpó a los cristianos."},
{"q":"El nacimiento de Julio Verne","risposta":1828,"curiosita":"Julio Verne nació el 8 de febrero de 1828 en Nantes. Escribió Veinte mil leguas de viaje submarino, La vuelta al mundo en 80 días y Viaje al centro de la Tierra, imaginando submarinos y viajes espaciales mucho antes de que existieran."},
{"q":"El nacimiento de Victor Hugo","risposta":1802,"curiosita":"Hugo nació el 26 de febrero de 1802 en Besanzón. Los miserables y Nuestra Señora de París son sus obras más famosas. Cuando murió en 1885, 2 millones de personas asistieron a su funeral."},
{"q":"El nacimiento de Alessandro Volta","risposta":1745,"curiosita":"Volta nació el 18 de febrero de 1745 en Como. Inventó la pila eléctrica en 1800, la primera fuente de corriente continua. El voltio lleva su nombre."},
{"q":"El nacimiento de Américo Vespucio","risposta":1454,"curiosita":"Vespucio nació el 9 de marzo de 1454 en Florencia. Exploró las costas de Sudamérica y comprendió que era un continente nuevo, no Asia. El cartógrafo Waldseemüller lo llamó 'América' en su honor."},
{"q":"El nacimiento de Rafael","risposta":1483,"curiosita":"Rafael Sanzio nació el 6 de abril de 1483 en Urbino. Murió el día de su cumpleaños, el 6 de abril de 1520, con solo 37 años. Su obra más célebre es La escuela de Atenas."},
{"q":"El nacimiento de Caravaggio","risposta":1571,"curiosita":"Michelangelo Merisi da Caravaggio nació en 1571 en Milán. Revolucionó la pintura con un claroscuro dramático. Mató a un hombre en una riña en 1606 y vivió como fugitivo hasta su muerte."},
{"q":"El nacimiento de Tiziano","risposta":1488,"curiosita":"Tiziano nació hacia 1488 en Pieve di Cadore. Murió en 1576 con unos 88 años, algo excepcional en la época. Era el pintor favorito del emperador Carlos V."},
{"q":"El nacimiento de Maquiavelo","risposta":1469,"curiosita":"Nicolás Maquiavelo nació el 3 de mayo de 1469 en Florencia. Escribió El príncipe en 1513, en el exilio. 'Maquiavélico' ha entrado en todos los idiomas para describir la política sin escrúpulos."},
{"q":"La fundación de Constantinopla","risposta":330,"curiosita":"Constantino I fundó Constantinopla el 11 de mayo del 330 d. C. en el antiguo emplazamiento de Bizancio. Fue la capital del Imperio bizantino durante más de 1.000 años, hasta 1453."},
{"q":"El Edicto de Milán (libertad de culto en el Imperio romano)","risposta":313,"curiosita":"En el 313 d. C. Constantino I promulgó el Edicto de Milán, que garantizaba la libertad religiosa en el Imperio romano y puso fin a la persecución de los cristianos."},
{"q":"El nacimiento de Rainer Maria Rilke","risposta":1875,"curiosita":"Rilke nació el 4 de diciembre de 1875 en Praga. Las Elegías de Duino y las Cartas a un joven poeta son sus obras más queridas. Murió de leucemia en 1926; la leyenda la relaciona con una espina de rosa."},
{"q":"El gran terremoto de Lisboa","risposta":1755,"curiosita":"El 1 de noviembre de 1755 un terremoto devastó Lisboa. El tsunami y los incendios mataron a decenas de miles de personas. Voltaire escribió Cándido en parte como respuesta a la catástrofe."},
{"q":"El nacimiento de Erasmo de Róterdam","risposta":1469,"curiosita":"Erasmo nació un 28 de octubre, hacia 1466-69, en Róterdam. Fue el principal intelectual del humanismo del norte de Europa. El programa universitario que lleva su nombre ha permitido a millones de estudiantes estudiar en el extranjero."},
{"q":"El nacimiento de Tomás Moro","risposta":1478,"curiosita":"Tomás Moro nació el 7 de febrero de 1478 en Londres. Escribió Utopía en 1516. Enrique VIII lo hizo decapitar en 1535 por negarse a reconocerlo como cabeza de la Iglesia de Inglaterra."},
{"q":"La publicación del Systema Naturae de Linneo","risposta":1735,"curiosita":"Carlos Linneo publicó el Systema Naturae en 1735 y sentó las bases de la nomenclatura binomial. Hoy cada ser vivo tiene un nombre científico basado en su sistema."},
{"q":"El nacimiento de Adam Smith","risposta":1723,"curiosita":"Adam Smith nació en junio de 1723 en Kirkcaldy, Escocia. La riqueza de las naciones (1776) es una de las bases de la economía moderna. La 'mano invisible' del mercado es idea suya."},
{"q":"El nacimiento de Immanuel Kant","risposta":1724,"curiosita":"Kant nació el 22 de abril de 1724 en Königsberg y casi nunca salió de su ciudad. Se cuenta que era tan puntual que los vecinos ponían en hora el reloj al verlo pasar."},
{"q":"El nacimiento de René Descartes","risposta":1596,"curiosita":"Descartes nació el 31 de marzo de 1596 en Francia. 'Pienso, luego existo' es su frase más famosa. Fundó la geometría analítica (el plano cartesiano lleva su nombre)."},
{"q":"El nacimiento de Voltaire","risposta":1694,"curiosita":"Voltaire nació el 21 de noviembre de 1694 en París. Se dice que bebía 40-50 tazas de café al día y estuvo dos veces encerrado en la Bastilla. Su Cándido es una de las novelas filosóficas más leídas de la historia."},
{"q":"El nacimiento de Jean-Jacques Rousseau","risposta":1712,"curiosita":"Rousseau nació el 28 de junio de 1712 en Ginebra. Sus ideas sobre el contrato social influyeron profundamente en la Revolución Francesa y en la filosofía política moderna."},
{"q":"El inicio de la construcción del Partenón","risposta":-447,"curiosita":"El Partenón se construyó entre el 447 y el 438 a. C. en la Acrópolis de Atenas por encargo de Pericles. Se mantuvo casi intacto 2.000 años, hasta que una explosión lo dañó gravemente en 1687."},
{"q":"El nacimiento de Hipócrates","risposta":-460,"curiosita":"Hipócrates nació hacia el 460 a. C. en la isla de Cos. Se le considera el padre de la medicina. El juramento hipocrático sigue siendo la base ética de la profesión médica."},
{"q":"La batalla de las Termópilas","risposta":-480,"curiosita":"En el 480 a. C., 300 espartanos dirigidos por Leónidas contuvieron durante tres días al ejército persa de Jerjes. Murieron casi todos, pero su resistencia ayudó a Grecia a organizar el contraataque."},
{"q":"La fundación de Cartago (estimación)","risposta":-814,"curiosita":"Cartago se fundó hacia el 814 a. C. por colonos fenicios de Tiro. Se convirtió en la gran rival de Roma en el Mediterráneo. De aquí partió Aníbal para cruzar los Alpes."},
{"q":"El nacimiento de Aníbal","risposta":-247,"curiosita":"Aníbal Barca nació en el 247 a. C. en Cartago. En el 218 a. C. cruzó los Alpes con 37 elefantes e infligió a Roma algunas de las peores derrotas de su historia, pero nunca la conquistó."},
{"q":"El saqueo de Roma por los visigodos","risposta":410,"curiosita":"En el 410 d. C. los visigodos de Alarico saquearon Roma durante tres días: era la primera vez en 800 años que la ciudad caía ante un enemigo extranjero. San Agustín escribió La ciudad de Dios como respuesta."},
{"q":"La exploración de Sudamérica por Vespucio","risposta":1499,"curiosita":"Américo Vespucio exploró las costas de Sudamérica en 1499-1500 y comprendió que era un continente desconocido, no Asia. Por eso el continente lleva su nombre."},
{"q":"El nacimiento de Francisco de Goya","risposta":1746,"curiosita":"Goya nació el 30 de marzo de 1746 en Fuendetodos, España. Pintor de cámara de Carlos IV, se quedó sordo en 1792 y su obra se volvió cada vez más oscura. Sus 'Pinturas negras' están entre las más inquietantes del arte occidental."},
{"q":"El nacimiento de Giacomo Leopardi","risposta":1798,"curiosita":"Leopardi nació el 29 de junio de 1798 en Recanati. Su 'pesimismo cósmico' lo convirtió en el mayor poeta italiano del Romanticismo. L'Infinito es su poema más célebre."},
{"q":"La fundación de la UNESCO","risposta":1945,"curiosita":"La UNESCO se fundó el 16 de noviembre de 1945 en Londres. Su misión es promover la paz y la seguridad a través de la educación, la ciencia y la cultura. Tiene 194 Estados miembros."},
{"q":"La publicación de la Crítica de la razón pura de Kant","risposta":1781,"curiosita":"Kant publicó la Crítica de la razón pura en 1781, tras 11 años de reflexión. Se considera una de las obras más importantes de la filosofía occidental."},
{"q":"La fundación de la FIFA","risposta":1904,"curiosita":"La FIFA se fundó el 21 de mayo de 1904 en París por 7 países europeos. Hoy tiene 211 federaciones miembro, más que los Estados miembros de la ONU."},
{"q":"El primer Mundial de fútbol","risposta":1930,"curiosita":"El primer Mundial se jugó en Uruguay en 1930 y lo ganó el anfitrión. Solo participaron 13 selecciones: casi todas las europeas renunciaron por el largo viaje en barco."},
{"q":"El nacimiento de Pelé","risposta":1940,"curiosita":"Pelé nació el 23 de octubre de 1940 en Três Corações, Brasil. Marcó más de 1.200 goles en su carrera y ganó tres Mundiales (1958, 1962, 1970): el único jugador que lo ha logrado."},
{"q":"El nacimiento de Muhammad Ali","risposta":1942,"curiosita":"Muhammad Ali nació el 17 de enero de 1942 en Louisville, Kentucky. Fue campeón mundial de los pesos pesados a los 22 años. Se negó a ir a Vietnam y le quitaron el título durante más de tres años."},
{"q":"El nacimiento de Ayrton Senna","risposta":1960,"curiosita":"Senna nació el 21 de marzo de 1960 en São Paulo y ganó 3 títulos mundiales de F1. Murió el 1 de mayo de 1994 en el Gran Premio de San Marino, en Imola; desde entonces la seguridad en la F1 ha mejorado muchísimo."},
{"q":"El primer Mundial de Fórmula 1","risposta":1950,"curiosita":"El primer Campeonato del Mundo de F1 se disputó en 1950. Nino Farina, con Alfa Romeo, fue el primer campeón, y el Gran Premio de Gran Bretaña en Silverstone fue la primera carrera."},
{"q":"El nacimiento de Roger Federer","risposta":1981,"curiosita":"Federer nació el 8 de agosto de 1981 en Basilea. Ganó 20 títulos de Grand Slam y muchos lo consideran el mejor tenista de todos los tiempos."},
{"q":"Los primeros Juegos Olímpicos modernos","risposta":1896,"curiosita":"Los primeros Juegos Olímpicos modernos se celebraron en Atenas en 1896, con 241 atletas de 14 países. Las mujeres no podían competir: lo hicieron por primera vez en París en 1900."},
{"q":"La fundación de la Scuderia Ferrari","risposta":1929,"curiosita":"Enzo Ferrari fundó la Scuderia Ferrari en Módena en 1929 como equipo de carreras para los coches de Alfa Romeo. El primer coche con el nombre Ferrari salió en 1947."},
{"q":"El nacimiento de Enzo Ferrari","risposta":1898,"curiosita":"Enzo Ferrari nació el 18 de febrero de 1898 en Módena. Construyó un imperio del motor a partir de su pasión por las carreras y murió en 1988 a los 90 años."},
{"q":"El nacimiento de Michael Jackson","risposta":1958,"curiosita":"Michael Jackson nació el 29 de agosto de 1958 en Gary, Indiana. Thriller (1982) es el álbum más vendido de la historia. Hizo el moonwalk por primera vez en televisión el 25 de marzo de 1983."},
{"q":"El nacimiento de Madonna","risposta":1958,"curiosita":"Madonna nació el 16 de agosto de 1958 en Bay City, Míchigan. Es la solista femenina que más discos ha vendido en la historia: más de 300 millones."},
{"q":"El nacimiento de David Bowie","risposta":1947,"curiosita":"Bowie nació el 8 de enero de 1947 en Londres y vendió más de 100 millones de discos. Sus ojos parecían de dos colores por la anisocoria: una pupila quedó dilatada tras un puñetazo en la adolescencia."},
{"q":"El nacimiento de Freddie Mercury","risposta":1946,"curiosita":"Freddie Mercury nació el 5 de septiembre de 1946 en Zanzíbar. Su nombre real era Farrokh Bulsara. Bohemian Rhapsody sigue siendo una de las canciones más escuchadas de todos los tiempos."},
{"q":"El nacimiento de Elvis Presley","risposta":1935,"curiosita":"Elvis nació el 8 de enero de 1935 en Tupelo, Misisipi. Vendió más de 500 millones de discos y sigue siendo uno de los artistas que más ingresan, décadas después de su muerte en 1977."},
{"q":"El nacimiento de John Lennon","risposta":1940,"curiosita":"Lennon nació el 9 de octubre de 1940 en Liverpool. Fundó los Beatles en 1960. Fue asesinado el 8 de diciembre de 1980 frente al edificio Dakota de Nueva York."},
{"q":"La primera emisión pública de radio","risposta":1920,"curiosita":"La primera emisión comercial regular de radio se hizo el 2 de noviembre de 1920 desde la KDKA de Pittsburgh, con los resultados de las elecciones presidenciales de EE. UU."},
{"q":"La invención de la World Wide Web por Berners-Lee","risposta":1989,"curiosita":"Tim Berners-Lee propuso la World Wide Web en 1989 mientras trabajaba en el CERN de Ginebra. La primera web se puso en línea el 6 de agosto de 1991. Nunca la patentó: se la regaló al mundo."},
{"q":"El nacimiento de Stephen Hawking","risposta":1942,"curiosita":"Hawking nació el 8 de enero de 1942 en Oxford, justo 300 años después de la muerte de Galileo. Le diagnosticaron ELA a los 21 años y le dieron 2 años de vida; vivió 55 más."},
{"q":"La publicación de 1984 de George Orwell","risposta":1949,"curiosita":"George Orwell publicó 1984 el 8 de junio de 1949, pocos meses antes de morir. Introdujo el Gran Hermano, el doblepensar y la neolengua, y es una de las novelas más vendidas de todos los tiempos."},
{"q":"El nacimiento de Woody Allen","risposta":1935,"curiosita":"Woody Allen nació el 1 de diciembre de 1935 en Brooklyn. Dirigió casi una película al año durante casi 50 años y ganó 4 Óscar."},
{"q":"La fundación de Netflix","risposta":1997,"curiosita":"Reed Hastings y Marc Randolph fundaron Netflix el 29 de agosto de 1997 como servicio de alquiler de DVD por correo. Pasó al streaming en 2007."}];
